# -- v1 apply_mask_highlight_torch (splatting_gui.py:62)
def apply_mask_highlight_torch(frames, mask):
    """Visualize the occlusion mask ON the splat preview (view-only):
    magenta tint whose opacity follows the mask value, plus a bright green
    outline at the 0.5 boundary — so warp/divergence changes to the holes are
    directly visible on the image. frames [B,3,H,W], mask [B,1,H,W]."""
    import torch.nn.functional as _F
    tint = torch.tensor([1.0, 0.15, 0.9], device=frames.device, dtype=frames.dtype).view(1, 3, 1, 1)
    a = 0.45 * mask
    out = frames * (1.0 - a) + tint * a
    hard = (mask > 0.5).float()
    edge = (_F.max_pool2d(hard, 3, stride=1, padding=1) - hard).clamp(0, 1)
    edge_c = torch.tensor([0.15, 1.0, 0.2], device=frames.device, dtype=frames.dtype).view(1, 3, 1, 1)
    out = out * (1.0 - edge) + edge_c * edge
    return out.clamp(0.0, 1.0)


import tkinter as _tkinter


class _Var:
    """One v1 tk variable, over the job's settings store.

    Built by _make_var as a subclass of the tkinter class v1 declared that
    variable as (VAR_TYPES), because v1 code branches on it:
    SidecarConfigManager.sync_to_gui converts by isinstance(var, tk.DoubleVar)
    and friends. No Tk root is created -- tkinter's __init__ is never run.
    """

    def __init__(self, store, key):
        self._store = store
        self._key = key

    def __del__(self):
        pass

    def get(self):
        return self._store.get(self._key)

    def set(self, value):
        self._store.set(self._key, value)
        self._store.fire(self._key)

    def trace_add(self, _mode, callback):
        """A real trace: v1 reacts to writes (Border mode, convergence...)."""
        self._store.traces.setdefault(self._key, []).append(callback)
        return str(id(callback))

    def trace_remove(self, *_a, **_k):
        pass

    def __str__(self):
        return self._key + "_var"


_TK_CLASSES = {"StringVar": _tkinter.StringVar, "DoubleVar": _tkinter.DoubleVar,
               "IntVar": _tkinter.IntVar, "BooleanVar": _tkinter.BooleanVar}
_VAR_CLASSES = {name: type("_" + name, (_Var, cls), {}) for name, cls in _TK_CLASSES.items()}


def _make_var(store, key):
    """A _Var of the class v1 declared `key`_var as (StringVar if unknown)."""
    cls = _VAR_CLASSES.get(VAR_TYPES.get(key + "_var", "StringVar"), _VAR_CLASSES["StringVar"])
    return cls(store, key)


class _Plain:
    """A tk variable nobody else sees: the previewer's own labels."""

    def __init__(self, value=None):
        self._value = value

    def get(self):
        return self._value

    def set(self, value):
        self._value = value


class _Store:
    """The settings a job runs on, and what it wrote back."""

    def __init__(self):
        self.values: Dict[str, Any] = {}
        self.writes: Dict[str, Any] = {}
        self.traces: Dict[str, list] = {}

    def fire(self, key):
        """Tk runs a variable's write traces as the write happens."""
        for callback in list(self.traces.get(key, ())):
            try:
                callback(key + "_var", "", "write")
            except Exception:
                logger.debug("Trace on %s failed", key, exc_info=True)

    def get(self, key):
        return self.values.get(key)

    def set(self, key, value):
        self.values[key] = value
        self.writes[key] = value

    def take_writes(self) -> Dict[str, Any]:
        out, self.writes = self.writes, {}
        return out


class _Widget:
    """Any widget a copied method pokes: accepts everything, shows nothing."""

    def __init__(self, **options):
        self._options = dict(options)

    def configure(self, **kw):
        self._options.update(kw)

    config = configure

    def cget(self, key):
        return self._options.get(key)

    def winfo_children(self):
        return []

    def __getattr__(self, _name):
        return lambda *a, **k: None


class _Label(_Widget):
    """v1's status label: its text goes to the hooks."""

    def __init__(self, hooks):
        super().__init__()
        self._hooks = hooks

    def configure(self, **kw):
        if "text" in kw:
            self._options["text"] = kw["text"]
            self._hooks.status(str(kw["text"] or ""))

    config = configure


