    # ---- faster preview: the pre-processed depth, cached ---------------------

    def _process_depth_batch(self, **kwargs):
        """v1's _process_depth_batch, remembered: a slider that acts after the
        pre-processing (disparity, borders, mask, warp, Special FX, the view)
        re-renders without redoing ~0.25 s of dilate/blur. The key is the
        exact input (its bytes) and everything else the result depends on.
        Not while dragging: the GPU pass is cheaper than the hash."""
        if FAST["on"]:
            return self._v1_process_depth_batch(**kwargs)
        arr = np.ascontiguousarray(kwargs["batch_depth_numpy_raw"])
        digest = hashlib.blake2b(arr.view(np.uint8).reshape(-1), digest_size=16)
        digest.update((str(arr.shape) + str(arr.dtype)).encode())
        others = tuple(sorted((k, repr(v)) for k, v in kwargs.items() if k != "batch_depth_numpy_raw"))
        try:
            regions = (json.dumps(self.dilate_regions.to_dict(), sort_keys=True)
                       if self.dilreg_enabled_var.get() else "")
        except Exception:
            regions = repr(id(self.dilate_regions))
        key = (FAST["on"], digest.hexdigest(), others, bool(self.skip_lowres_preproc_var.get()),
               str(self.depth_blur_left_mix_var.get()), regions,
               int(getattr(self.previewer, "last_loaded_frame_index", 0) or 0))
        hit = self._depth_cache.get(key)
        if hit is not None:
            self._depth_cache.move_to_end(key)
            return hit.copy()
        out = self._v1_process_depth_batch(**kwargs)
        self._depth_cache[key] = out.copy()
        while len(self._depth_cache) > 6:
            self._depth_cache.popitem(last=False)
        return out

