    def on_slider_release(self, event=None, immediate: bool = False):
        """v1 renders now (immediate) or after a 350 ms debounce. Here the
        debounce is the end of the current job: the worker renders once if
        anything asked (see preview.py _do) -- v1's clip load skips its own
        render because this call makes it."""
        if immediate:
            self._render_requested = False
            self._perform_delayed_preview_update()
        else:
            self._render_requested = True

    def _perform_delayed_preview_update(self):
        if self.previewer.source_readers:
            self.previewer.update_preview()

