    # -- v1 SplatterGUI._auto_converge_worker (splatting_gui.py:1135)
    def _auto_converge_worker(self, rgb_path, depth_map_path, process_length, fallback_value, gamma, mode):
        """Worker thread for running the Auto-Convergence calculation."""

        # Use the extracted ConvergenceEstimatorWrapper
        # Now returns average, peak, and (NEW) max_edge_l, max_edge_r
        res = self.convergence_estimator.estimate_convergence(
            rgb_path=rgb_path,
            depth_path=depth_map_path,
            process_length=int(process_length),
            gamma=float(gamma),
            fallback_value=float(fallback_value),
            stop_event=self.stop_event,
            scan_borders=True,  # Enable combined scan
        )

        new_anchor_avg, new_anchor_peak, max_edge_l, max_edge_r = res

        # Determine TV range compensation for border calculation
        # This is fast if called here (usually cached or metadata-only)
        if hasattr(self, "border_scanner"):
            # We don't have a VideoReader here, so we'll let BorderScanner handle it or calculate it later.
            # For simplicity, we can pass the path and let BorderScanner handle it if we modify it,
            # but actually BorderScanner._get_tv_compensation uses VideoReader.
            # We'll just pass the depth_map_path and do it in the UI thread or use a helper.
            pass

        # Use self.after to safely update the GUI from the worker thread
        self.after(
            0,
            lambda: self._complete_auto_converge_update(
                new_anchor_avg, new_anchor_peak, max_edge_l, max_edge_r, fallback_value, mode, depth_map_path
            ),
        )

    # -- v1 SplatterGUI._on_clip_navigate_with_cache_clear (splatting_gui.py:1169)
    def _on_clip_navigate_with_cache_clear(self):
        """Callback for clip navigation that clears auto-convergence cache, restores
        slider values from the new clip's sidecar, then saves if auto-save is on."""
        # Clear auto-convergence cache when switching clips
        self.cache.clear_auto_conv()
        self._auto_conv_cache = self.cache.auto_conv  # keep alias in sync

        # Clear processing information display
        self.clear_processing_info()

        # v2 (2026-10-17): the guard is kept -- this runs before the index moves, so a
        # cleared guard re-loaded the clip being LEFT over its edits (see gen PATCHES).
        # The new clip is restored by its own load.

        # Restore GUI sliders from this clip's sidecar BEFORE any auto-save, so we
        # never overwrite an existing sidecar with stale/default slider values.
        sidecar_existed = self._restore_sliders_from_current_sidecar()

        # Save sidecar if auto-save is enabled (inlined from old _auto_save_current_sidecar).
        # Only auto-save when a sidecar already existed for this clip; otherwise a fresh
        # clip with no sidecar would be written out at default values on first navigation.
        if self.auto_save_sidecar_var.get() and sidecar_existed:
            self._save_current_sidecar_data(is_auto_save=True)

    # -- v1 SplatterGUI._restore_sliders_from_current_sidecar (splatting_gui.py:1194)
    def _restore_sliders_from_current_sidecar(self) -> bool:
        """Restore GUI sliders from the current preview clip's sidecar, if one exists.

        Idempotent per clip: re-invoking for the same depth map (e.g. because both
        the clip-navigate and clip-state callbacks fire on a single load) only
        applies the restore once. Returns True if a sidecar file existed for the
        current clip, regardless of whether the restore was applied this call.

        update_gui_from_sidecar() itself no-ops when "Update Slider from Sidecar"
        is disabled or when no sidecar exists, so this is safe to call broadly.
        """
        try:
            if not (
                getattr(self, "previewer", None)
                and 0 <= self.previewer.current_video_index < len(self.previewer.video_list)
            ):
                return False
            depth_map = self.previewer.video_list[self.previewer.current_video_index].get("depth_map")
            if not depth_map:
                return False

            sidecar_ext = self.APP_CONFIG_DEFAULTS["SIDECAR_EXT"]
            sidecar_folder = self._get_sidecar_base_folder()
            sc_path = self.sidecar_manager.resolve_sidecar_path(depth_map, sidecar_folder, sidecar_ext)
            sidecar_existed = os.path.exists(sc_path)

            # Skip the actual slider sync if we already restored this exact clip,
            # so the two load callbacks don't double-apply or clobber live edits.
            if getattr(self, "_last_restored_depth_map", None) != depth_map:
                self.update_gui_from_sidecar(depth_map)
                self._last_restored_depth_map = depth_map

            return sidecar_existed
        except Exception as e:
            logger.debug(f"Sidecar restore skipped: {e}")
            return False

