    # -- v1 SplatterGUI._kf_current_frame (splatting_gui.py:1249)
    def _kf_current_frame(self) -> int:
        """The frame the Keyframe buttons and preview interpolation act on:
        wherever the previewer's scrubber is right now."""
        try:
            return int(float(self.previewer.frame_scrubber_var.get()))
        except Exception:
            return self._clip_frame()

    # -- v1 SplatterGUI._kf_all_var_names (splatting_gui.py:1257)
    def _kf_all_var_names(self):
        for group in self.KEYFRAME_VAR_GROUPS.values():
            for name in group:
                yield name

    # -- v1 SplatterGUI._kf_capture_current_values (splatting_gui.py:1262)
    def _kf_capture_current_values(self) -> dict:
        """Snapshots every keyframeable slider's current value."""
        values = {}
        for name in self._kf_all_var_names():
            var = getattr(self, name, None)
            if var is not None:
                values[name] = self._safe_float(var, 0.0)
        return values

    # -- v1 SplatterGUI._kf_has_clip_loaded (splatting_gui.py:1271)
    def _kf_has_clip_loaded(self) -> bool:
        return bool(
            getattr(self, "previewer", None)
            and 0 <= self.previewer.current_video_index < len(self.previewer.video_list)
        )

    # -- v1 SplatterGUI._kf_add_keyframe (splatting_gui.py:1277)
    def _kf_add_keyframe(self, kind: str):
        """'Add Static/Dynamic Keyframe': snapshots the current values onto
        whatever frame the scrubber is on right now."""
        if not self._kf_has_clip_loaded():
            messagebox.showwarning("Keyframe", "Please load a video in the Previewer first.")
            return
        frame = self._kf_current_frame()
        values = self._kf_capture_current_values()
        self.keyframe_track.set_keyframe(frame, kind, values)
        self._kf_redraw_markers()
        self._kf_refresh_summary()
        label = "Static" if kind == "static" else "Dynamic"
        self.status_label.configure(text=f"{label} keyframe set at frame {frame + 1}.")
        self._kf_autosave()
        try:
            # A keyframe changes what this exact frame renders -- refresh it
            # now rather than waiting for the next scrub.
            self.previewer.update_preview()
        except Exception:
            pass

    # -- v1 SplatterGUI._kf_clear_current (splatting_gui.py:1298)
    def _kf_clear_current(self):
        """'Clear Current': removes the keyframe at the scrubber's frame, if any."""
        if not self._kf_has_clip_loaded():
            return
        frame = self._kf_current_frame()
        if self.keyframe_track.clear_frame(frame):
            self._kf_redraw_markers()
            self._kf_refresh_summary()
            self.status_label.configure(text=f"Cleared keyframe at frame {frame + 1}.")
            self._kf_autosave()
            try:
                self.previewer.update_preview()
            except Exception:
                pass
        else:
            self.status_label.configure(text=f"No keyframe at frame {frame + 1} to clear.")

    # -- v1 SplatterGUI._kf_clear_all (splatting_gui.py:1315)
    def _kf_clear_all(self):
        """'Clear All': removes every keyframe for the current clip, after confirming."""
        if not self._kf_has_clip_loaded() or self.keyframe_track.is_empty():
            return
        if not messagebox.askyesno(
            "Clear All Keyframes",
            "Remove every keyframe for this clip? This cannot be undone.",
        ):
            return
        self.keyframe_track.clear_all()
        self._kf_redraw_markers()
        self._kf_refresh_summary()
        self.status_label.configure(text="Cleared all keyframes for this clip.")
        self._kf_autosave()
        try:
            self.previewer.update_preview()
        except Exception:
            pass

    # -- v1 SplatterGUI._kf_autosave (splatting_gui.py:1334)
    def _kf_autosave(self):
        """Keyframe edits are per-clip data like Hole Shift
        regions -- persist immediately when auto-save is on, same as those."""
        try:
            if self.auto_save_sidecar_var.get():
                self._save_current_sidecar_data(is_auto_save=True)
        except Exception:
            pass

    # -- v1 SplatterGUI._kf_interpolated_values_for_frame (splatting_gui.py:1527)
    def _kf_interpolated_values_for_frame(self, frame_idx: int) -> Optional[dict]:
        """This clip's keyframed values at `frame_idx`, or None for none.

        The math is core.common.keyframes.KeyframeTrack.values_at, shared
        with the export render so the two cannot drift apart. This wrapper
        exists for the attribute guard: the track is created per clip and
        callers here can run before there is one.
        """
        track = getattr(self, "keyframe_track", None)
        if track is None:
            return None
        return track.values_at(frame_idx)

    # -- v1 SplatterGUI._kf_apply_interpolation_to_settings (splatting_gui.py:1540)
    def _kf_apply_interpolation_to_settings(self, settings: dict, frame_idx: int, border_mode: str) -> None:
        """Overrides `settings` in place with this frame's interpolated
        keyframe values. No-ops entirely when the current clip has no
        keyframes, so behavior for every non-keyframed clip is unchanged.

        Border Width/Bias are handled separately from KEYFRAME_SETTINGS_VAR_MAP
        because they only mean something once run through Border Mode's
        Auto Basic / Manual math -- reproduced here to match
        get_current_preview_settings's own branch exactly.
        """
        kf_values = self._kf_interpolated_values_for_frame(frame_idx)
        if not kf_values:
            return

        for settings_key, var_name in self.KEYFRAME_SETTINGS_VAR_MAP.items():
            if var_name in kf_values:
                settings[settings_key] = kf_values[var_name]

        if border_mode in ("Auto Basic", "Manual") and (
            "border_width_var" in kf_values or "border_bias_var" in kf_values
        ):
            w = kf_values.get("border_width_var", self._safe_float(self.border_width_var))
            b = kf_values.get("border_bias_var", self._safe_float(self.border_bias_var))
            if border_mode == "Auto Basic":
                l_pct, r_pct = w, w
            else:  # Manual
                if b <= 0:
                    l_pct, r_pct = w, w * (1.0 + b)
                else:
                    l_pct, r_pct = w * (1.0 - b), w
            settings["left_border_pct"] = l_pct
            settings["right_border_pct"] = r_pct

    # -- v1 SplatterGUI._fb_source_aspect_ratio (splatting_gui.py:1607)
    def _fb_source_aspect_ratio(self) -> Optional[float]:
        """Display aspect ratio (width/height) of the current clip's source
        video, cached per path. None when no clip is loaded or the probe
        fails -- callers treat None as 'offer no presets, free slider only'."""
        try:
            if not self._kf_has_clip_loaded():
                return None
            idx = self.previewer.current_video_index
            src = self.previewer.video_list[idx].get("source_video")
            if not src or not os.path.exists(src):
                return None
            cache = getattr(self, "_fb_ar_cache", None)
            if cache is None:
                cache = self._fb_ar_cache = {}
            if src in cache:
                return cache[src]
            ar = None
            try:
                cap = cv2.VideoCapture(src)
                w = float(cap.get(cv2.CAP_PROP_FRAME_WIDTH) or 0.0)
                h = float(cap.get(cv2.CAP_PROP_FRAME_HEIGHT) or 0.0)
                cap.release()
                if w > 0.0 and h > 0.0:
                    ar = w / h
            except Exception:
                ar = None
            cache[src] = ar
            return ar
        except Exception:
            return None

    # -- v1 SplatterGUI._fb_offered_presets (splatting_gui.py:1638)
    def _fb_offered_presets(self, src_ar: Optional[float]):
        """The (label, ratio) presets to offer for a given source AR: only
        those strictly wider than the source (you can't letterbox to a
        narrower or equal ratio). None AR -> none offered."""
        offered = []
        if src_ar is None:
            return offered
        for label, ratio in self.FRAME_BREAK_PRESETS:
            if (ratio - src_ar) > self.FRAME_BREAK_PRESET_EPS:
                offered.append((label, ratio))
        return offered

    # -- v1 SplatterGUI._fb_refresh_presets (splatting_gui.py:1650)
    def _fb_refresh_presets(self):
        """Rebuilds the Letterbox Size button row for the current clip's source AR.
        Called on every clip load (from update_gui_from_sidecar).

        Same offer rule the dropdown used, just expressed as widgets: a preset
        whose ratio isn't wider than the source has no button at all. Every
        button is forgotten and re-packed each time rather than toggled
        individually, so the survivors always sit in FRAME_BREAK_PRESETS order
        (pack appends, so a button re-shown on its own would jump to the end).
        """
        buttons = getattr(self, "fb_preset_buttons", None)
        if not buttons:
            return
        src_ar = self._fb_source_aspect_ratio()
        offered = self._fb_offered_presets(src_ar)
        self._fb_preset_ar = {label: ratio for label, ratio in offered}
        offered_labels = [label for label, _ in offered]
        try:
            for _label, btn in buttons:
                btn.pack_forget()
            none_label = getattr(self, "fb_preset_none_label", None)
            if none_label is not None:
                none_label.pack_forget()
            caption = getattr(self, "fb_preset_label", None)
            if caption is not None:
                caption.pack_forget()

            # The caption leads the row, so it is packed before the buttons --
            # pack appends, and a label added afterwards would sit at the end.
            show_caption = bool(offered_labels) or src_ar is None
            if caption is not None and show_caption:
                caption.pack(side="left", padx=(0, 4))

            for label, btn in buttons:
                if label in offered_labels:
                    btn.pack(side="left", padx=1)

            # Two ways to have nothing on offer, and they want opposite things.
            # No clip yet: say so, because the row will fill in once one loads.
            # A source already as wide as every preset (2.39:1): there is
            # nothing to letterbox it to and never will be for this clip, so
            # the whole row goes -- caption included -- exactly as the buttons
            # do, rather than leaving a caption labelling nothing.
            if not offered_labels and src_ar is None and none_label is not None:
                none_label.configure(text="no clip loaded")
                none_label.pack(side="left", padx=(2, 0))

            self._fb_sync_preset_to_bars(src_ar, offered)
        except Exception as e:
            logger.debug(f"Frame Break preset refresh skipped: {e}")

    # -- v1 SplatterGUI._fb_sync_preset_to_bars (splatting_gui.py:1705)
    def _fb_sync_preset_to_bars(self, src_ar, offered):
        """Light whichever offered preset the current Bar Size actually is, or
        none at all (Custom).

        The combobox could get away with showing a stale label, because a label
        in a box reads as "last thing picked". A LIT BUTTON reads as "this is
        what the bars are", so it has to be true: a clip load zeroes Bar Size,
        and a sidecar restore sets it to a saved number that may or may not be
        a standard ratio. Recomputing from the bar fraction covers both, and
        relights the right button for a clip saved at, say, 2.39:1 -- which the
        old code couldn't do at all, since the sidecar stores the fraction and
        never the label."""
        label_now = "Custom"
        if src_ar:
            bars = self._safe_float(self.frame_break_bars_var, 0.0)
            if bars > 0.0:
                for label, ratio in offered:
                    frac = max(0.0, min(1.0, 1.0 - (src_ar / ratio)))
                    if abs(bars - round(frac, 4)) <= self._FB_PRESET_MATCH_EPS:
                        label_now = label
                        break
        if self.fb_preset_var.get() != label_now:
            self._fb_setting_preset = True
            try:
                self.fb_preset_var.set(label_now)
            finally:
                self._fb_setting_preset = False

    # -- v1 SplatterGUI._fb_on_preset_selected (splatting_gui.py:1733)
    def _fb_on_preset_selected(self, *_event):
        """Letterbox Size button -> set the Bar Size slider to the fraction that letters
        this source down to the chosen ratio: bar_fraction = 1 - src/target.

        Runs as the radiobutton's command, so fb_preset_var already holds the
        clicked label by the time we're called. Re-clicking the lit button just
        recomputes the same fraction, which is harmless."""
        label = self.fb_preset_var.get()
        if label == "Custom":
            return
        target = getattr(self, "_fb_preset_ar", {}).get(label)
        src_ar = self._fb_source_aspect_ratio()
        if not target or not src_ar:
            return
        frac = max(0.0, min(1.0, 1.0 - (src_ar / target)))
        # Guard so the var's trace doesn't immediately knock the buttons back
        # to "Custom" (unlit) -- this write IS the preset.
        self._fb_setting_preset = True
        try:
            self.frame_break_bars_var.set(round(frac, 4))
        finally:
            self._fb_setting_preset = False
        try:
            for updater in getattr(self, "slider_label_updaters", []):
                updater()
        except Exception:
            pass
        try:
            self.on_slider_release(None)
        except Exception:
            pass

    # -- v1 SplatterGUI._fb_on_bars_changed (splatting_gui.py:1765)
    def _fb_on_bars_changed(self, *_args):
        """Manual Bar Size drags drop back to Custom, which unlights every
        Letterbox Size button (no button carries "Custom" as its value). A preset-driven
        write sets _fb_setting_preset first, so it's exempt."""
        if getattr(self, "_fb_setting_preset", False):
            return
        try:
            combo_var = getattr(self, "fb_preset_var", None)
            if combo_var is not None and combo_var.get() != "Custom":
                combo_var.set("Custom")
        except Exception:
            pass

    # -- v1 SplatterGUI._apply_preview_brightness (splatting_gui.py:1789)
    def _apply_preview_brightness(self, rgb_np, params):
        """View-only exposure lift: multiplies the finished preview frame so
        dark scenes are easier to judge on screen. No-op at 1.0 (the default),
        so every preview is byte-identical until this is touched. Operates
        purely on the already-rendered display array returned to the
        previewer -- it has no path back into the depth map, the warp, or
        anything encoded/written to disk."""
        try:
            b = float(params.get("preview_brightness", 1.0))
        except Exception:
            b = 1.0
        if abs(b - 1.0) < 1e-6:
            return rgb_np
        return np.clip(rgb_np.astype(np.float32) * b, 0, 255).astype(np.uint8)

    # -- v1 SplatterGUI._fb_maybe_apply (splatting_gui.py:1804)
    def _fb_maybe_apply(self, rgb_np, depth_2d, params, preview_source, sbs=False):
        """Composites Frame Break onto a finished preview RGB frame, if the
        feature is active and the current mode is a viewer-facing one. No-ops
        (returns the input untouched) otherwise, so every non-frame-break
        preview is byte-for-byte unchanged."""
        try:
            bars = float(params.get("frame_break_bars", 0.0))
        except Exception:
            bars = 0.0
        if bars <= 0.0 or preview_source not in self._FB_APPLY_MODES:
            return rgb_np
        try:
            thr = float(params.get("frame_break_thresh", 1.0))
        except Exception:
            thr = 1.0
        edge = (
            float(params.get("frame_break_erode_left", 0.0)),
            float(params.get("frame_break_erode_right", 0.0)),
            float(params.get("frame_break_erode_global", 0.0)),
            float(params.get("frame_break_edge_blur", 0.0)),
        )
        d = depth_2d
        if sbs and d is not None:
            # SBS frame is [left|right]; tile the (source-aligned) depth to
            # match so the protrusion mask lands on both halves. The right eye
            # is warped, so its mask is approximate -- fine for a preview.
            try:
                d = np.concatenate([d, d], axis=1)
            except Exception:
                d = None
        try:
            return self._apply_frame_break(rgb_np, d, bars, thr, edge)
        except Exception as e:
            logger.debug(f"Frame Break composite skipped: {e}")
            return rgb_np

    # -- v1 SplatterGUI._apply_frame_break (splatting_gui.py:1840)
    def _apply_frame_break(self, rgb_np, depth_2d, bars_amount, break_thresh, edge=(0.0, 0.0, 0.0, 0.0)):
        """Draw top/bottom letterbox bars covering `bars_amount` of the height,
        and let near pixels (depth >= break_thresh) show through them.

        The protrusion mask and its Edge fine-tuning come from the shared
        core.common.frame_break module, so this preview and the baked render
        mask are byte-identical. The mask is applied as a SOFT mask (0..255
        alpha): with no Edge Blur it is pure 0/255 (the original hard cutout);
        with Edge Blur > 0 the break boundary is feathered and composites
        smoothly. break_thresh >= 1.0 means solid bars (nothing protrudes)."""
        H, W = rgb_np.shape[:2]
        bar_px = int(round((float(bars_amount) * 0.5) * H))
        if bar_px <= 0:
            return rgb_np
        bar_px = min(bar_px, H // 2 if H > 1 else 0)
        if bar_px <= 0:
            return rgb_np

        out = rgb_np.copy()

        alpha = None  # (H, W) float 0..1: 1 = show subject, 0 = solid bar
        if depth_2d is not None and float(break_thresh) < 1.0:
            mask = fb_mask.build_protrusion_mask(depth_2d, float(break_thresh), H, W)
            mask = fb_mask.morph_protrusion_mask(mask, edge[0], edge[1], edge[2], edge[3])
            alpha = mask.astype(np.float32) / 255.0

        for region in (slice(0, bar_px), slice(H - bar_px, H)):
            if alpha is None:
                out[region] = 0
            else:
                a = alpha[region][..., None]  # (bar, W, 1)
                # bar is black, so kept = image*a + black*(1-a) = image*a.
                out[region] = np.clip(out[region].astype(np.float32) * a, 0, 255).astype(np.uint8)
        return out

    # -- v1 SplatterGUI._safe_float (splatting_gui.py:1941)
    def _safe_float(self, var, default=0.0):
        """Safely convert StringVar/BooleanVar to float."""
        try:
            val = var.get()
            if isinstance(val, bool):
                return float(val)
            return float(val)
        except (ValueError, TypeError, tk.TclError):
            return default

    # -- v1 SplatterGUI._compute_clip_global_depth_stats (splatting_gui.py:1951)
    def _compute_clip_global_depth_stats(self, depth_map_path: str, chunk_size: int = 100) -> Tuple[float, float]:
        """
        Computes the global min and max depth values from a depth video by reading
        it in chunks. Used only for the preview's GN cache.

        Delegates to AnalysisService.compute_clip_global_depth_stats (no GUI deps).
        """
        result = AnalysisService.compute_clip_global_depth_stats(
            depth_map_path=depth_map_path, stop_event=self.stop_event, chunk_size=chunk_size
        )
        # Cache the result so downstream code can read it -- not a stopped or failed
        # scan's (0.0, 1.0) (v2: bug sweep A4)
        if not (self.stop_event is not None and self.stop_event.is_set()) and tuple(result) != (0.0, 1.0):
            self.cache.store_clip_norm(depth_map_path, result[0], result[1])
        return result

