    # -- v1 SplatterGUI._preview_edit_signature (splatting_gui.py:6112)
    def _preview_edit_signature(self) -> str:
        """Digest of the region/stroke edits that affect a rendered frame.

        Cheap and conservative: any change to either correction set produces a
        different digest, which invalidates the previewer's frame buffer.
        """
        import hashlib
        import json as _json

        parts = []
        try:
            if self.dilreg_enabled_var.get() and not self.dilate_regions.is_empty():
                parts.append(_json.dumps(self.dilate_regions.to_dict(), sort_keys=True))
            else:
                parts.append("dil:off")
        except Exception:
            parts.append("dil:err")
        try:
            # Keyframes themselves are already folded into settings (boost_*,
            # depth_gamma, etc. are overwritten with interpolated values
            # above), so this only needs to catch edits to the TRACK -- add,
            # clear, retype -- that don't change what's currently on screen at
            # this exact frame but must still invalidate other cached frames.
            track = getattr(self, "keyframe_track", None)
            if track is not None and not track.is_empty():
                parts.append(_json.dumps(track.to_list(), sort_keys=True))
            else:
                parts.append("kf:off")
        except Exception:
            parts.append("kf:err")

        return hashlib.md5("|".join(parts).encode("utf-8")).hexdigest()[:16]

    # -- v1 SplatterGUI._get_current_sidecar_paths_and_data (splatting_gui.py:6145)
    def _get_current_sidecar_paths_and_data(self) -> Optional[Tuple[str, str, dict]]:
        """Helper to get current file path, sidecar path, and existing data (merged with defaults)."""
        if not hasattr(self, "previewer") or not self.previewer.video_list or self.previewer.current_video_index == -1:
            return None

        current_index = self.previewer.current_video_index
        depth_map_path = self.previewer.video_list[current_index].get("depth_map")

        if not depth_map_path:
            return None

        # Determine sidecar path using the centralized manager
        sidecar_folder = self._get_sidecar_base_folder()
        sidecar_ext = self.APP_CONFIG_DEFAULTS["SIDECAR_EXT"]
        json_sidecar_path = self.sidecar_manager.resolve_sidecar_path(depth_map_path, sidecar_folder, sidecar_ext)

        # Load existing data (merged with defaults) to preserve non-GUI parameters like overlap/bias
        current_data = self.sidecar_manager.load_sidecar_data(json_sidecar_path)

        return json_sidecar_path, depth_map_path, current_data

    # -- v1 SplatterGUI.on_auto_convergence_mode_select (splatting_gui.py:6833)
    def on_auto_convergence_mode_select(self, event):
        """
        Handles selection in the Auto-Convergence combo box.
        If a mode is selected, it checks the cache and runs the calculation if needed.
        """
        mode = self.auto_convergence_mode_var.get()

        if mode == "Off":
            # self._auto_conv_cache = {"Average": None, "Peak": None} # Clear cache on Off
            return

        if self._is_auto_conv_running:
            logger.warning("Auto-Converge calculation is already running. Please wait.")
            return

        # Check cache logic
        cached_value = None
        if mode == "Hybrid":
            if self._auto_conv_cache.get("Average") is not None and self._auto_conv_cache.get("Peak") is not None:
                cached_value = (self._auto_conv_cache["Average"] + self._auto_conv_cache["Peak"]) / 2.0
        elif self._auto_conv_cache.get(mode) is not None:
            cached_value = self._auto_conv_cache[mode]

        if cached_value is not None:
            # Value is cached, apply it immediately

            # 1. Set the Tkinter variable to the cached value (needed for the setter)
            self.zero_disparity_anchor_var.set(f"{cached_value:.2f}")

            # 2. Call the programmatic setter to update the slider position and its label
            if self.set_convergence_value_programmatically:
                try:
                    self.set_convergence_value_programmatically(cached_value)
                except Exception as e:
                    logger.error(f"Error calling convergence setter on cache hit: {e}")

            # 3. Update status label
            self.status_label.configure(text=f"Auto-Converge ({mode}): Loaded cached value {cached_value:.2f}")

            # 4. Refresh preview
            self.on_slider_release(None)

            return

        # Cache miss, run the calculation (using the existing run_preview_auto_converge logic)
        self.run_preview_auto_converge(force_run=True)

    # -- v1 SplatterGUI._live_conv_key (splatting_gui.py:6911)
    def _live_conv_key(self, preview_source: str):
        """What the kept eyes are OF: clip, frame, view and eye setup.

        A drag only slides eyes whose key still matches -- a frame scrubbed
        to from the preview cache, a different view, or a Dual Eye change
        since the render leaves the preview alone until the release.
        """
        pv = getattr(self, "previewer", None)
        try:
            frame = int(float(pv.frame_scrubber_var.get())) if pv is not None else -1
        except Exception:
            frame = -1
        return (
            getattr(pv, "current_video_index", None),
            frame,
            preview_source,
            bool(self.dual_eye_var.get()),
            round(self._safe_float(self.dual_eye_bias_var, 0.5), 4),
        )

    # -- v1 SplatterGUI._process_depth_batch (splatting_gui.py:7099)
    def _v1_process_depth_batch(
        self,
        batch_depth_numpy_raw: np.ndarray,
        depth_stream_info: Optional[dict],
        depth_gamma: float,
        depth_dilate_size_x: float,
        depth_dilate_size_y: float,
        depth_blur_size_x: float,
        depth_blur_size_y: float,
        is_low_res_task: bool,
        max_raw_value: float,
        global_depth_min: float,
        global_depth_max: float,
        depth_dilate_left: float = 0.0,
        depth_blur_left: float = 0.0,
        depth_blur_left_mix: Optional[float] = None,
        debug_batch_index: int = 0,
        debug_frame_index: int = 0,
        debug_task_name: str = "PreProcess",
    ) -> np.ndarray:
        """
        Unified depth processor. Pre-processes filters in float space.
        Gamma is now unified to occur in normalized space.
        """
        # Dev Tools: allow skipping ALL low-res preprocessing (gamma/dilate/blur)
        skip_preprocessing = False
        if (
            is_low_res_task
            and getattr(self, "skip_lowres_preproc_var", None) is not None
            and self.skip_lowres_preproc_var.get()
        ):
            skip_preprocessing = True

        try:
            mix_f = float(depth_blur_left_mix if depth_blur_left_mix is not None
                          else self.depth_blur_left_mix_var.get())
        except Exception:
            mix_f = 0.5

        return process_depth_batch(
            dilate_regions=(
                self.dilate_regions if self.dilreg_enabled_var.get() else None
            ),
            frame_indices=[int(getattr(self.previewer, "last_loaded_frame_index", 0) or 0)],
            batch_depth_numpy_raw=batch_depth_numpy_raw,
            depth_gamma=depth_gamma,
            depth_dilate_size_x=depth_dilate_size_x,
            depth_dilate_size_y=depth_dilate_size_y,
            depth_blur_size_x=depth_blur_size_x,
            depth_blur_size_y=depth_blur_size_y,
            max_raw_value=max_raw_value,
            depth_dilate_left=depth_dilate_left,
            depth_blur_left=depth_blur_left,
            depth_blur_left_mix=mix_f,
            skip_preprocessing=skip_preprocessing,
            debug_task_name=debug_task_name,
        )

    # -- v1 SplatterGUI._preview_processing_callback (splatting_gui.py:7155)
    def _preview_processing_callback(self, source_frames: dict, params: dict) -> Optional[Image.Image]:
        """
        Callback for VideoPreviewer. Performs splatting on a single frame for preview.
        """
        import time

        t_start = time.perf_counter()
        # NOTE: Do not clear the 'Current Processing Information' panel on every preview render.
        # Clearing here caused filename/task info to briefly appear and then reset to N/A each time the preview updates.

        if not globals()["CUDA_AVAILABLE"]:
            logger.error("Preview processing requires a CUDA-enabled GPU.")
            return None

        logger.debug("--- Starting Preview Processing Callback ---")

        left_eye_tensor = source_frames.get("source_video")
        depth_tensor_raw = source_frames.get("depth_map")

        if left_eye_tensor is None or depth_tensor_raw is None:
            logger.error("Preview failed: Missing source video or depth map tensor.")
            return None

        # --- Get latest settings and Preview Mode ---
        params = self.get_current_preview_settings()
        if not params:
            logger.error("Preview failed: Could not get current preview settings.")
            return None

        preview_source = self.preview_source_var.get()

        is_low_res_preview = preview_source in ["Splat Result(Low)", "Occlusion Mask(Low)"]

        # Determine the target resolution for the preview tensor
        W_orig = left_eye_tensor.shape[3]
        H_orig = left_eye_tensor.shape[2]

        t_setup = time.perf_counter()

        # ----------------------------------------------------------------------
        # NEW SIDECAR LOGIC FOR PREVIEW
        # ----------------------------------------------------------------------
        depth_map_path = None
        if 0 <= self.previewer.current_video_index < len(self.previewer.video_list):
            current_source_dict = self.previewer.video_list[self.previewer.current_video_index]
            depth_map_path = current_source_dict.get("depth_map")

        gui_config = {  # v2: the settings handed in first -- this frame's keyframes are in them
            "convergence_plane": float(params.get("convergence_point", self.zero_disparity_anchor_var.get())),
            "max_disparity": float(params.get("max_disp", self.max_disp_var.get())),
            "gamma": float(params.get("depth_gamma", self.depth_gamma_var.get())),
        }

        merged_config = gui_config.copy()

        # Set final parameters from the merged config
        params["convergence_point"] = merged_config["convergence_plane"]
        params["max_disp"] = merged_config["max_disparity"]
        params["depth_gamma"] = merged_config["gamma"]

        # ----------------------------------------------------------------------
        # END NEW SIDECAR LOGIC FOR PREVIEW
        # ----------------------------------------------------------------------

        W_target, H_target = W_orig, H_orig

        if is_low_res_preview:
            try:
                W_target_requested = int(self.pre_res_width_var.get())

                if W_target_requested <= 0:
                    W_target_requested = W_orig  # Fallback

                # 1. Calculate aspect-ratio-correct height based on the requested width
                aspect_ratio = W_orig / H_orig
                H_target_calculated = int(round(W_target_requested / aspect_ratio))

                # 2. Ensure both W and H are divisible by 2 for codec compatibility
                W_target = W_target_requested if W_target_requested % 2 == 0 else W_target_requested + 1
                H_target = H_target_calculated if H_target_calculated % 2 == 0 else H_target_calculated + 1

                # 3. Handle potential extreme fallbacks
                if W_target <= 0 or H_target <= 0:
                    W_target, H_target = W_orig, H_orig
                    logger.warning("Low-Res preview: Calculated dimensions invalid, falling back to original.")
                else:
                    logger.debug(
                        f"Low-Res preview: AR corrected target {W_target}x{H_target}. (Original W: {W_orig}, H: {H_orig})"
                    )

                # Resize Left Eye to aspect-ratio-correct low-res target for consistency
                left_eye_tensor_resized = F.interpolate(
                    left_eye_tensor.cuda(), size=(H_target, W_target), mode="bilinear", align_corners=False
                )
            except Exception as e:
                logger.error(
                    f"Low-Res preview failed during AR calculation/resize: {e}. Falling back to original res.",
                    exc_info=True,
                )
                W_target, H_target = W_orig, H_orig
                left_eye_tensor_resized = left_eye_tensor.cuda()
        else:
            left_eye_tensor_resized = left_eye_tensor.cuda()  # Use original res

        # --- OPTIMIZATION: Early exit for non-processed views ---
        if preview_source == "Original (Left Eye)":
            left_np = (
                left_eye_tensor_resized.squeeze(0).permute(1, 2, 0).cpu().numpy() * 255
            ).astype(np.uint8)
            logger.debug("Preview: Early exit for 'Original (Left Eye)' mode.")
            return Image.fromarray(left_np)

        t_resize_rgb = time.perf_counter()

        logger.debug(f"Preview Params: {params}")
        logger.debug(f"Target Resolution: {W_target}x{H_target} (Low-Res: {is_low_res_preview})")

        # Determine if we should skip pre-processing for low-res
        skip_preprocessing = False
        if (
            is_low_res_preview
            and getattr(self, "skip_lowres_preproc_var", None) is not None
            and self.skip_lowres_preproc_var.get()
        ):
            skip_preprocessing = True

        # --- Process Depth Frame ---
        depth_numpy_raw = depth_tensor_raw.squeeze(0).permute(1, 2, 0).cpu().numpy()
        logger.debug(
            f"Raw depth numpy shape: {depth_numpy_raw.shape}, range: [{depth_numpy_raw.min():.2f}, {depth_numpy_raw.max():.2f}]"
        )

        # Ensure depth pre-processing happens at the same resolution as the *render* pipeline.
        # - Full-res preview: pre-proc at clip resolution (W_orig/H_orig).
        # - Low-res preview: pre-proc at clip resolution, then downscale to low-res AFTER pre-proc.
        #   This matches the low-res render ordering and avoids the "extra thick" low-res preview look.
        W_preproc, H_preproc = (W_orig, H_orig)

        # OPTIMIZATION: If skipping pre-processing, we can resize directly to target resolution
        if skip_preprocessing:
            W_preproc, H_preproc = (W_target, H_target)

        if depth_numpy_raw.ndim == 2:
            depth_numpy_raw = depth_numpy_raw[:, :, None]
        if depth_numpy_raw.shape[0] != H_preproc or depth_numpy_raw.shape[1] != W_preproc:
            try:
                had_singleton_channel = depth_numpy_raw.ndim == 3 and depth_numpy_raw.shape[2] == 1
                interp = (
                    cv2.INTER_LINEAR
                    if (W_preproc > depth_numpy_raw.shape[1] or H_preproc > depth_numpy_raw.shape[0])
                    else cv2.INTER_AREA
                )
                depth_numpy_raw = cv2.resize(depth_numpy_raw, (W_preproc, H_preproc), interpolation=interp)
                if had_singleton_channel and depth_numpy_raw.ndim == 2:
                    depth_numpy_raw = depth_numpy_raw[:, :, None]
                logger.debug(f"Preview depth resized for pre-proc: {depth_numpy_raw.shape}")
            except Exception as e:
                logger.error(
                    f"Preview depth resize (pre-proc) failed: {e}. Continuing with raw depth resolution.", exc_info=True
                )

        t_resize_depth = time.perf_counter()

        # 1. DETERMINE MAX CONTENT VALUE FOR THE FRAME (for AutoGain scaling)
        # We need the max *raw* value of the depth frame content
        max_raw_content_value = depth_numpy_raw.max()
        if max_raw_content_value < 1.0:
            max_raw_content_value = 1.0  # Fallback for already 0-1 normalized content

        # --- NEW: Get Global Normalization Policy for Preview (Sidecar check) ---
        enable_global_norm = params.get("enable_global_norm", False)

        # Policy Check: Sidecar existence forces GN OFF
        sidecar_exists = False
        if depth_map_path:
            sidecar_folder = self._get_sidecar_base_folder()
            depth_map_basename = os.path.splitext(os.path.basename(depth_map_path))[0]
            sidecar_ext = self.APP_CONFIG_DEFAULTS["SIDECAR_EXT"]

            json_sidecar_path = os.path.join(sidecar_folder, f"{depth_map_basename}{sidecar_ext}")
            sidecar_exists = os.path.exists(json_sidecar_path)

        if sidecar_exists:
            # Policy: If sidecar exists, GN is forced OFF
            enable_global_norm = False

        # --- NEW: Determine Global Min/Max from cache if GN is ON ---
        global_min, global_max = 0.0, 1.0

        if enable_global_norm and depth_map_path:
            cached_norm = self.cache.get_clip_norm(depth_map_path)
            if cached_norm is None:
                # --- CACHE MISS: Run the slow scan synchronously ---
                logger.info(
                    f"Preview GN: Cache miss for {os.path.basename(depth_map_path)}. Running clip-local scan..."
                )
                global_min, global_max = self._compute_clip_global_depth_stats(depth_map_path)
            else:
                # --- CACHE HIT: Use cached values ---
                global_min, global_max = cached_norm
                logger.debug(
                    f"Preview GN: Cache hit for {os.path.basename(depth_map_path)}. Min/Max: {global_min:.3f}/{global_max:.3f}"
                )

        # --- END NEW CACHE LOGIC ---

        # Determine the correct scaling base (max RAW value) using Render-parity logic
        # 1. Scaling Logic
        depth_bits = getattr(self.previewer, "_depth_bit_depth", 0)

        # If previewer hasn't tagged the bit depth, or it's default 8, double-check from file info
        # to ensure parity with the renderer's ffprobe-based detection.
        if (depth_bits <= 8) and depth_map_path:
            if not hasattr(self, "_depth_bits_cache"):
                self._depth_bits_cache = {}
            if depth_map_path not in self._depth_bits_cache:
                info = get_video_stream_info(depth_map_path)
                self._depth_bits_cache[depth_map_path] = _infer_depth_bit_depth(info)
            depth_bits = max(depth_bits, self._depth_bits_cache[depth_map_path])

        max_val_in_frame = float(depth_numpy_raw.max())

        if depth_bits == 16:
            max_raw_value = 65535.0
        elif depth_bits == 12:
            max_raw_value = 4095.0
        elif depth_bits == 10:
            max_raw_value = 1023.0
        elif depth_bits == 8:
            max_raw_value = 255.0
        else:
            # Fallback auto-detection for truly untagged sources (e.g. numpy arrays)
            if max_val_in_frame > 256.0:
                max_raw_value = 1023.0
            elif max_val_in_frame > 1.05:
                max_raw_value = 255.0
            else:
                max_raw_value = 1.0

        final_scaling_factor = max_raw_value

        # NOTE: if enable_global_norm is True, we use global_max/min for the normalization curve.
        # But final_scaling_factor is the "base" we scale back up to after normalization
        # so that dilation/blur kerels (which are pixel-based) feel consistent.
        preview_global_max = global_max if enable_global_norm else 1.0
        # logger.debug(f"Preview: BitDepth={depth_bits}, RawMax={max_val_in_frame:.1f}, Dtype={depth_numpy_raw.dtype}, GN={enable_global_norm}. Scaling Base: {final_scaling_factor:.1f}")

        # --- UNIFICATION STEP: Match Render Scaling Logic ---

        # Render engine passes global_depth_max=1.0 for assume_raw_input=True
        # because the input is expected to be scaled by max_expected_raw_value inside normalize_and_gamma.

        batch_depth_normalized = normalize_and_gamma_depth(
            batch_depth_numpy_raw=np.expand_dims(depth_numpy_raw, axis=0),
            assume_raw_input=not enable_global_norm,
            global_depth_max=preview_global_max,
            global_depth_min=global_min if enable_global_norm else 0.0,
            max_expected_raw_value=final_scaling_factor,
            zero_disparity_anchor_val=params.get("convergence_point", 0.0),
            depth_gamma=params["depth_gamma"],
            debug_task_name="Preview",
        )

        # --- Peak-anchored Depth Boost: resolve the clip depth peak ---------
        # Warp-domain peak for boost anchoring. Sources, in order:
        #   sidecar depth_max_raw -> GN clip-scan cache (auto-saved to sidecar
        #   so batch renders inherit it deterministically) -> 1.0 flat anchor.
        # GN-on clips are normalized to full range, so peak is 1.0 by design.
        depth_peak_warp = 1.0
        _peak_src = "flat 1.0"
        _boost_on = (self._safe_float(self.boost_amount_var, 0.0) > 0.0
                     or self._safe_float(self.pop_amount_var, 0.0) > 0.0
                     or any(float((_v or {}).get(_n, 0.0) or 0.0) > 0.0
                            for _f, _k, _v in (self.keyframe_track.items_sorted()
                                               if getattr(self, 'keyframe_track', None) is not None else ())
                            for _n in ('boost_amount_var', 'pop_amount_var')))
        if (_boost_on or preview_source == "Boost Zone"):
            if enable_global_norm and not sidecar_exists:
                _peak_src = "GN domain (1.0 by construction)"
            else:
                _raw_peak = None
                try:
                    if sidecar_exists and json_sidecar_path and os.path.exists(json_sidecar_path):
                        with open(json_sidecar_path, "r") as _f:
                            _sc = json.load(_f) or {}
                        _v = _sc.get("depth_max_raw")
                        if _v:
                            _raw_peak = float(_v)
                            _peak_src = "sidecar"
                except Exception:
                    _raw_peak = None
                if _raw_peak is None and depth_map_path:
                    _cn = self.cache.get_clip_norm(depth_map_path)
                    if _cn is None:
                        logger.info(
                            "Boost peak: no depth_max_raw in sidecar and GN cache cold — "
                            "running one-time clip depth scan..."
                        )
                        try:
                            _gmin, _gmax = self._compute_clip_global_depth_stats(depth_map_path)
                            _cn = (_gmin, _gmax)
                        except Exception as _e:
                            logger.warning(f"Boost peak: clip scan failed ({_e}); flat 1.0 anchor.")
                            _cn = None
                    _hi = float(_cn[1]) if _cn else 0.0
                    if _cn and final_scaling_factor > 1.0 and _hi <= 1.0:
                        _cn = None  # the scan's failure value, not a clip's peak
                    if _cn:
                        _raw_peak = _hi / max(final_scaling_factor, 1.0)  # a fraction of the code range
                        _peak_src = "GN clip scan"
                        # Auto-save so batch renders inherit the anchor (option a:
                        # deterministic, file-based, never per-frame).
                        if _raw_peak < 0.999 and json_sidecar_path:
                            try:
                                _sc = {}
                                if os.path.exists(json_sidecar_path):
                                    with open(json_sidecar_path, "r") as _f:
                                        _sc = json.load(_f) or {}
                                if abs(float(_sc.get("depth_max_raw", 0) or 0) - _raw_peak) > 1e-4:
                                    _sc["depth_max_raw"] = round(_raw_peak, 4)
                                    # whole or not at all (audit 2026-09-28, minor)
                                    from core.common.atomic_json import write_json_atomic
                                    write_json_atomic(json_sidecar_path, _sc, indent=4)
                                    logger.info(
                                        f"Boost peak: auto-saved depth_max_raw={_raw_peak:.4f} -> "
                                        f"{os.path.basename(json_sidecar_path)}"
                                    )
                            except Exception as _e:
                                logger.warning(f"Boost peak: sidecar auto-save failed: {_e}")
                if _raw_peak is not None and 0.0 < _raw_peak < 0.999:
                    # Convert RAW peak to warp domain with the pipeline's own
                    # function on a scalar — identical args to the real call.
                    try:
                        _pk = normalize_and_gamma_depth(
                            batch_depth_numpy_raw=np.full(
                                (1, 1, 1, 1), _raw_peak * final_scaling_factor, dtype=np.float32
                            ),
                            assume_raw_input=not enable_global_norm,
                            global_depth_max=preview_global_max,
                            global_depth_min=global_min if enable_global_norm else 0.0,
                            max_expected_raw_value=final_scaling_factor,
                            zero_disparity_anchor_val=params.get("convergence_point", 0.0),
                            depth_gamma=params["depth_gamma"],
                            debug_task_name="PreviewPeak",
                        )
                        depth_peak_warp = float(np.asarray(_pk).reshape(-1)[0])
                    except Exception as _e:
                        logger.warning(f"Boost peak: conversion failed ({_e}); flat 1.0 anchor.")
                        depth_peak_warp = 1.0
                elif _raw_peak is None and not enable_global_norm:
                    logger.info(
                        "Boost peak: the clip scan found no peak; using the flat 1.0 anchor."
                    )

        _clean = float(params.get("submask_clean", 0.0) or 0.0)
        if _clean > 0:
            _cd = batch_depth_normalized
            _cm = self._preview_submask_frame(_cd.shape[1], _cd.shape[2], bool(params.get("flip_horizontal", False)),
                                              params.get("submask_grow", 0.0), params.get("submask_soften", 0.0))
            if _cm is not None:
                from core.splatting.subtitle_mask_adjust import clean_depth
                _px = _clean * getattr(self, "_preview_submask_scale", 1.0)
                batch_depth_normalized = np.stack([clean_depth(_cd[i], _cm, _px) for i in range(_cd.shape[0])])

        # Scale back to max_raw_value range so dilation/blur work correctly
        batch_depth_for_processing = batch_depth_normalized * final_scaling_factor

        # Ensure 4D with 1 channel [Batch, H, W, 1] to match Render engine
        if batch_depth_for_processing.ndim == 3:
            batch_depth_for_processing = batch_depth_for_processing[..., None]

        depth_numpy_processed = self._process_depth_batch(
            batch_depth_numpy_raw=batch_depth_for_processing,
            depth_stream_info=None,
            depth_gamma=1.0,
            depth_dilate_size_x=params["depth_dilate_size_x"],
            depth_dilate_size_y=params["depth_dilate_size_y"],
            depth_blur_size_x=params["depth_blur_size_x"],
            depth_blur_size_y=params["depth_blur_size_y"],
            depth_dilate_left=params.get("depth_dilate_left", 0.0),
            depth_blur_left=params.get("depth_blur_left", 0.0),
            depth_blur_left_mix=params.get("depth_blur_left_mix"),
            is_low_res_task=is_low_res_preview,
            max_raw_value=final_scaling_factor,
            global_depth_min=0.0,
            global_depth_max=1.0,
            debug_task_name="Preview",
        )
        logger.debug(
            f"Processed depth numpy shape: {depth_numpy_processed.shape}, range: [{depth_numpy_processed.min():.2f}, {depth_numpy_processed.max():.2f}]"
        )

        # Low-Res preview: downscale the *processed* depth AFTER dilation/blur (matches render ordering).
        if is_low_res_preview and (
            depth_numpy_processed.shape[1] != H_target or depth_numpy_processed.shape[2] != W_target
        ):
            try:
                _d = depth_numpy_processed.squeeze(0)
                _interp = cv2.INTER_AREA if (W_target < _d.shape[1] and H_target < _d.shape[0]) else cv2.INTER_LINEAR
                _d = cv2.resize(_d, (W_target, H_target), interpolation=_interp)
                depth_numpy_processed = np.expand_dims(_d.astype(np.float32), axis=0)
                logger.debug(f"Low-Res preview: resized processed depth to target {W_target}x{H_target}.")
            except Exception as e:
                logger.error(
                    f"Low-Res preview post-preproc resize failed: {e}. Continuing with processed depth resolution.",
                    exc_info=True,
                )

        # Normalize back to 0..1
        depth_normalized = depth_numpy_processed.squeeze(0) / max(final_scaling_factor, 1.0)
        depth_normalized = np.clip(depth_normalized, 0, 1)
        logger.debug(
            f"Final normalized depth shape: {depth_normalized.shape}, range: [{depth_normalized.min():.2f}, {depth_normalized.max():.2f}]"
        )

        # Subtitle mask: pin masked pixels to the convergence anchor, the same
        # anchor-relative lerp the renderer applies (render_processor step 3.6).
        # Here for the same reason it is there: after dilate/blur and after the
        # 0..1 renormalisation, immediately before the warp, so neither bleeds
        # warped depth back into the protected text and the anchor is in the
        # same domain as the depth it is mixed into.
        _sub_h = depth_normalized.shape[0]
        _sub_w = depth_normalized.shape[1]
        _sub_m = self._preview_submask_frame(_sub_h, _sub_w, bool(params.get("flip_horizontal", False)),
                                             params.get("submask_grow", 0.0), params.get("submask_soften", 0.0))
        if _sub_m is not None:
            _sub_anchor = float(np.clip(float(params.get("convergence_point", 0.0))
                                        - float(params.get("submask_conv", 0.0) or 0.0), 0.0, 1.0))  # v2: Text Conv
            if depth_normalized.ndim == 3 and _sub_m.ndim == 2:
                _sub_m = _sub_m[..., None]
            depth_normalized = depth_normalized * (1.0 - _sub_m) + _sub_anchor * _sub_m
            depth_normalized = np.clip(depth_normalized, 0, 1)

        t_norm = time.perf_counter()

        # Send depth min/max to previewer for display in Depth Map mode
        if preview_source in ("Depth Map", "Depth Map (Color)"):
            if hasattr(self, "previewer") and self.previewer is not None:
                raw_min = float(depth_numpy_raw.min())
                raw_max = float(depth_numpy_raw.max())
                self.previewer.set_depth_minmax(raw_min, raw_max)

        # Cache the stereo projector for preview
        if not hasattr(self, "_preview_stereo_projector") or self._preview_stereo_projector is None:
            self._preview_stereo_projector = ForwardWarpStereo(occlu_map=True).cuda()
        stereo_projector = self._preview_stereo_projector

        # Ensure depth map is resized to the target resolution (low-res or original)
        disp_map_tensor = torch.from_numpy(depth_normalized).unsqueeze(0).unsqueeze(0).float().cuda()

        # Resize Disparity Map to match the (potentially resized) Left Eye
        if H_target != disp_map_tensor.shape[2] or W_target != disp_map_tensor.shape[3]:
            logger.debug(f"Resizing depth map to match target {W_target}x{H_target}.")
            disp_map_tensor = F.interpolate(
                disp_map_tensor, size=(H_target, W_target), mode="bilinear", align_corners=False
            )

        tv_disp_comp = 1.0
        if not enable_global_norm:
            try:
                if getattr(self, "previewer", None) is not None:
                    _bd = int(getattr(self.previewer, "_depth_bit_depth", 8) or 8)
                    _dpath = getattr(self.previewer, "_depth_path", None)
                    if _bd > 8 and _dpath:
                        if not hasattr(self, "_depth_color_range_cache"):
                            self._depth_color_range_cache = {}
                        if _dpath not in self._depth_color_range_cache:
                            _info = get_video_stream_info(_dpath)
                            self._depth_color_range_cache[_dpath] = str(
                                (_info or {}).get("color_range", "unknown")
                            ).lower()
                        if self._depth_color_range_cache.get(_dpath) == "tv":
                            tv_disp_comp = 1.0 / (DEPTH_VIS_TV10_WHITE_NORM - DEPTH_VIS_TV10_BLACK_NORM)
            except Exception:
                tv_disp_comp = 1.0

        # Preview-only depth/pop separation metrics (percent of screen width)
        # Uses a lightweight sampled scan of the current normalized depth map.
        try:
            if getattr(self, "previewer", None) is not None and hasattr(self.previewer, "set_depth_pop_metrics"):
                show_metrics = bool(self.depth_pop_enabled_var.get()) and (
                    preview_source in ("Anaglyph 3D", "Dubois Anaglyph", "Optimized Anaglyph",
                                       "ColorCode (Amber/Blue)", "ColorCode (Blue/Amber)",
                                       "Side-by-Side", "Side-by-Side (Cross-eye)", "Glasses-Free 3D")
                )
                if show_metrics:
                    _stride = 8  # sample stride for speed (1/64 pixels)
                    _sample = depth_normalized[::_stride, ::_stride]
                    _valid = (_sample > 0.001) & (_sample < 0.999)
                    if _valid.any():
                        _ds = _sample[_valid]
                        # Disparity percent of screen width (W cancels out):
                        # disp_pct = (depth - conv) * 2 * (max_disp / 20)
                        _disp_pct = (
                            (_ds - params["convergence_point"]) * 2.0 * (params["max_disp"] / 20.0) * tv_disp_comp
                        )
                        _min_pct = float(_disp_pct.min())
                        _max_pct = float(_disp_pct.max())
                        _depth_pct = max(0.0, -_min_pct)  # screen-behind
                        _pop_pct = float(_max_pct)  # screen-out (can be negative if all behind)
                    else:
                        _depth_pct, _pop_pct = 0.0, 0.0
                    sig = None
                    try:
                        _dp_path = getattr(self.previewer, "_depth_path", "")
                        sig = self._dp_total_signature(
                            _dp_path,
                            params.get("convergence_point", 0.0),
                            params.get("max_disp", 0.0),
                            params.get("depth_gamma", 1.0),
                        )
                    except Exception:
                        sig = None

                    try:
                        self.previewer.set_depth_pop_metrics(_depth_pct, _pop_pct, sig)
                    except TypeError:
                        self.previewer.set_depth_pop_metrics(_depth_pct, _pop_pct)
                else:
                    try:
                        self.previewer.set_depth_pop_metrics(None, None, None)
                    except TypeError:
                        self.previewer.set_depth_pop_metrics(None, None)
        except Exception:
            pass

        t_metrics = time.perf_counter()

        _rain_tensor = _rain_depth_tensor = None
        _rain_left = left_eye_tensor_resized
        # only for the views that show the warp: Depth Map, Mesh Warp, Boost Zone... threw
        # the separation away (bug sweep 2026-10-09, A6). The same views as needs_forward_warp
        # below (test_splatting checks the two lists agree).
        _rain_views = ("Splat Result", "Splat Result(Low)", "Anaglyph 3D", "Dubois Anaglyph",
                       "Optimized Anaglyph", "ColorCode (Amber/Blue)", "ColorCode (Blue/Amber)",
                       "Side-by-Side", "Side-by-Side (Cross-eye)", "Wigglegram", "SBS + Mesh",
                       "Glasses-Free 3D",
                       "Occlusion Mask", "Occlusion Mask(Low)")
        try:
            if preview_source in _rain_views:
                from core.splatting.rain import preview_rain
                _rain_tensor, _rain_depth_tensor = preview_rain(self, left_eye_tensor_resized, disp_map_tensor, params)
        except Exception:
            logger.warning("Rain preview failed", exc_info=True)
        # Web (personal/web, not released): the clean frame is warped with the scene's depth cleaned of
        # DepthCrafter's strand bands, as the render does
        if _rain_tensor is not None:
            try:
                from core.splatting.rain import preview_scene_depth
                _web_scene = preview_scene_depth(disp_map_tensor)
                if _web_scene is not None:
                    disp_map_tensor = _web_scene
            except Exception:
                logger.warning("Web preview depth failed", exc_info=True)
        if _rain_tensor is not None:
            left_eye_tensor_resized = (left_eye_tensor_resized - _rain_tensor).clamp(0.0, 1.0)

        # --- BRANCHING EXECUTION: Only run the warp needed for the current view ---
        needs_forward_warp = preview_source in (
            "Splat Result",
            "Splat Result(Low)",
            "Anaglyph 3D",
            "Dubois Anaglyph",
            "Optimized Anaglyph",
            "ColorCode (Amber/Blue)",
            "ColorCode (Blue/Amber)",
            "Side-by-Side",
            "Side-by-Side (Cross-eye)",
            "Wigglegram",
            "Glasses-Free 3D",
            "SBS + Mesh",
            "Occlusion Mask",
            "Occlusion Mask(Low)",
        )
        needs_mesh_warp = preview_source in ("Mesh Warp", "SBS + Mesh")

        right_eye_tensor = None
        occlusion_mask = None
        left_occ_mask = None  # dual-eye preview only

        # Filled by execute_forward_warp with the final per-eye disparity.
        _disp_probe: dict = {}

        if needs_forward_warp:
            _dual_eye_preview = bool(self.dual_eye_var.get())
            if _dual_eye_preview:
                # Dual-eye preview: warp BOTH eyes with the disparity split by the
                # bias, exactly like the render (same execute_forward_warp path), so
                # convergence, borders, and per-eye disocclusions preview faithfully.
                left_warped, left_occ_mask, right_eye_tensor_raw, occlusion_mask = execute_forward_warp(
                    stereo_projector=stereo_projector,
                    source_tensor=left_eye_tensor_resized,
                    depth_tensor=disp_map_tensor,
                    target_width=W_target,
                    max_disp=params["max_disp"],
                    zero_disparity_anchor_val=params["convergence_point"],
                    input_bias=0.0,
                    tv_disp_comp=tv_disp_comp,
                    debug_task_name="Preview",
                    mask_mode=params.get("mask_mode", "SC"),
                    splat_backend=params.get("splat_backend", "SC"),
                    hybrid_sensitivity=params.get("hybrid_sensitivity", 50.0),
                    hybrid_taper=params.get("hybrid_taper", False),
                    m2s_fix_strength=params.get("m2s_fix_strength", 1.0),
                    dual_eye=True,
                    pop_amount=params.get("pop_amount", 0.0),
                    dual_eye_bias=self._safe_float(self.dual_eye_bias_var, 0.5),
                    boost_thresh=params.get("boost_thresh", 0.85),
                    boost_amount=params.get("boost_amount", 0.0),
                    boost_curve=params.get("boost_curve", 2.0),
                    depth_peak=depth_peak_warp,
                    disp_probe=_disp_probe,
                )
                right_eye_tensor = right_eye_tensor_raw
                # Downstream stereo compositions (anaglyphs, SBS, wigglegram) pair
                # 'left_eye_tensor_resized' against the right warp. In dual-eye both
                # eyes are warped, so substitute the warped left. Modes that need the
                # true original (Original view, Depth Map, Mesh Warp) never set
                # needs_forward_warp, so they are unaffected by this rebinding.
                left_eye_tensor_resized = left_warped
            else:
                right_eye_tensor_raw, occlusion_mask = execute_forward_warp(
                    stereo_projector=stereo_projector,
                    source_tensor=left_eye_tensor_resized,
                    depth_tensor=disp_map_tensor,
                    target_width=W_target,
                    max_disp=params["max_disp"],
                    zero_disparity_anchor_val=params["convergence_point"],
                    input_bias=0.0,
                    tv_disp_comp=tv_disp_comp,
                    debug_task_name="Preview",
                    mask_mode=params.get("mask_mode", "SC"),
                    splat_backend=params.get("splat_backend", "SC"),
                    hybrid_sensitivity=params.get("hybrid_sensitivity", 50.0),
                    hybrid_taper=params.get("hybrid_taper", False),
                    m2s_fix_strength=params.get("m2s_fix_strength", 1.0),
                    pop_amount=params.get("pop_amount", 0.0),
                    boost_thresh=params.get("boost_thresh", 0.85),
                    boost_amount=params.get("boost_amount", 0.0),
                    boost_curve=params.get("boost_curve", 2.0),
                    depth_peak=depth_peak_warp,
                    disp_probe=_disp_probe,
                )
                right_eye_tensor = right_eye_tensor_raw

        if _rain_tensor is not None:
            _dual_rain = bool(needs_forward_warp and self.dual_eye_var.get())
            if needs_forward_warp:
                from core.splatting.rain import warp_rain
                _rl, _rr = warp_rain(
                    _rain_tensor, _rain_depth_tensor, float(self._safe_float(self.rain_amount_var, 1.0)), _dual_rain,
                    stereo_projector=stereo_projector, target_width=W_target, max_disp=params["max_disp"],
                    zero_disparity_anchor_val=params["convergence_point"], input_bias=0.0,
                    tv_disp_comp=tv_disp_comp, debug_task_name="Preview",
                    dual_eye_bias=self._safe_float(self.dual_eye_bias_var, 0.5),
                    pop=self._safe_float(self.rain_pop_var, 0.0),
                    pop_amount=params.get("pop_amount", 0.0), boost_thresh=params.get("boost_thresh", 0.85),
                    boost_amount=params.get("boost_amount", 0.0), boost_curve=params.get("boost_curve", 2.0),
                    depth_peak=depth_peak_warp,
                )
                if right_eye_tensor is not None:
                    right_eye_tensor = (right_eye_tensor + _rr).clamp(0.0, 1.0)
            if needs_forward_warp and _dual_rain:
                left_eye_tensor_resized = (left_eye_tensor_resized + _rl).clamp(0.0, 1.0)
            else:
                left_eye_tensor_resized = _rain_left

        # Cache the disparity the warp ACTUALLY used, straight from the probe
        # execute_forward_warp filled in. Recomputing it here would miss
        # depth_peak clamping and the dual-eye split, both of which change the
        # gaps -- so Hole Shift would show holes the render never makes.
        try:
            _probe_d = _disp_probe.get("right")
            if _probe_d is not None:
                self._warp_last_disp = _probe_d[0, 0].float().cpu().numpy()
            # The occlusion mask is what the Localized Dilate window turns into
            # clickable holes, so it is cached from the same render.
            if occlusion_mask is not None:
                self._dilreg_last_occ = occlusion_mask.detach()[0, 0].float().cpu().numpy()
            # The warped right eye, so the Localized Dilate window can show the
            # holes against the actual splat rather than a bare mask. Cached
            # regardless of preview source, so the window works from any view.
            if right_eye_tensor is not None:
                _sp = right_eye_tensor.detach()[0].permute(1, 2, 0)
                self._dilreg_last_splat = (
                    (_sp * 255.0).clamp(0, 255).to(torch.uint8).cpu().numpy()
                )
        except Exception as _e:
            logger.debug(f"Preview: warp cache failed: {_e}")

        # Holes move when a region's offsets change, so an open Localized Dilate
        # window is refreshed from every completed render. Marshalled onto the
        # Tk thread because this callback runs off it.
        for _cb in (self._dilreg_refresh,):
            if _cb is not None:
                try:
                    self.after(0, _cb)
                except Exception:
                    pass

        t_warp = time.perf_counter()

        # --- Apply black borders for Anaglyph and Wigglegram ---
        if right_eye_tensor is not None and preview_source in [
            "Anaglyph 3D",
            "Dubois Anaglyph",
            "Optimized Anaglyph",
            "ColorCode (Amber/Blue)",
            "ColorCode (Blue/Amber)",
            "Wigglegram",
            "Glasses-Free 3D",
        ]:
            l_pct = params.get("left_border_pct", 0.0)
            r_pct = params.get("right_border_pct", 0.0)

            l_px = int(round(l_pct * W_target / 100.0))
            r_px = int(round(r_pct * W_target / 100.0))

            if l_px > 0:
                # Left eye border (always on the logical left of the source)
                left_eye_tensor_resized[:, :, :, :l_px] = 0.0
            if r_px > 0:
                # Right eye border (always on the logical right of the source)
                right_eye_tensor[:, :, :, -r_px:] = 0.0

        if preview_source == "Splat Result" or preview_source == "Splat Result(Low)":
            final_tensor = right_eye_tensor
            # Mask highlighter (view-only): paint the disocclusion holes on the
            # splat so warp/divergence effects on the cutouts are obvious.
            if getattr(self, "mask_highlight_var", None) is not None and self.mask_highlight_var.get():
                if occlusion_mask is not None:
                    final_tensor = apply_mask_highlight_torch(final_tensor, occlusion_mask)
        elif preview_source == "Occlusion Mask" or preview_source == "Occlusion Mask(Low)":
            if left_occ_mask is not None:
                # Dual-eye: show [left mask | right mask] so the halved per-eye
                # disocclusion holes are directly visible.
                final_tensor = torch.cat([left_occ_mask, occlusion_mask], dim=3).repeat(1, 3, 1, 1)
            else:
                final_tensor = occlusion_mask.repeat(1, 3, 1, 1)
        elif preview_source == "Original (Left Eye)":
            final_tensor = left_eye_tensor_resized
        elif preview_source == "Boost Zone":
            # Depth Boost visualizer: paints WHICH pixels the boost touches and
            # HOW strongly, using the exact same apply_depth_boost the warp
            # runs (imported, not duplicated — cannot drift from the render).
            # ORANGE = boost is LIVE (Amount > 0), intensity = ramp weight.
            # CYAN   = zone-only preview (Amount is 0): what WOULD be boosted.
            # All-dark image => threshold sits above this clip's depth range,
            # so the boost is inert — lower the boost Threshold until the zone appears.
            d = torch.clip(depth_normalized, 0.0, 1.0)  # preview warp uses input_bias=0.0
            _amt = float(params.get("boost_amount", 0.0))
            _thr = float(params.get("boost_thresh", 0.85))
            _crv = float(params.get("boost_curve", 2.0))
            _knee = float(params.get("boost_knee", 0.0))
            _md = float(params.get("max_disp", 20.0))
            _live = boost_is_active(_amt, _md)
            _eff = _amt if _live else 1.0
            # Peak anchoring: evaluate the zone in the clip's own depth range,
            # mirroring execute_forward_warp's delta composition exactly.
            _pk = min(max(float(depth_peak_warp), 1e-3), 1.0)
            d_eval = torch.clamp(d / _pk, max=1.0) if _pk < 0.999 else d
            boosted = apply_depth_boost(
                d_eval, boost_thresh=_thr, boost_amount=_eff, boost_curve=_crv,
                max_disp=_md, boost_knee=_knee,
            )
            delta = (boosted - d_eval).clamp_min(0.0)
            # Normalize by the maximum possible boost (a depth-1.0 pixel) so
            # tint brightness = true ramp weight 0..1, scene-independent.
            _full = apply_depth_boost(
                torch.ones_like(d[..., :1, :1]), boost_thresh=_thr,
                boost_amount=_eff, boost_curve=_crv, max_disp=_md,
                boost_knee=_knee,
            ) - 1.0
            w = (delta / _full.clamp_min(1e-6)).clamp(0.0, 1.0)
            base = d.repeat(1, 3, 1, 1) * 0.55  # dimmed depth so the tint reads
            _col = (1.0, 0.55, 0.05) if _live else (0.05, 0.8, 1.0)
            tint = torch.tensor(_col, device=d.device, dtype=d.dtype).view(1, 3, 1, 1)
            final_tensor = (base * (1.0 - w) + tint * w).clamp(0.0, 1.0)
            try:
                cov = float((w > 0.01).float().mean()) * 100.0
                logger.info(
                    f"Boost Zone: {cov:.1f}% of pixels in zone | thr={_thr:.2f} "
                    f"crv={_crv:.1f} amt={_amt:.1f} ({'LIVE' if _live else 'inactive, zone preview'}) "
                    f"| frame depth max={float(d.max()):.3f} | peak anchor={_pk:.3f} ({_peak_src})"
                )
            except Exception:
                pass
        elif preview_source == "Depth Map":
            # Direct grayscale view (visualization-only TV-range expansion for 10-bit depth, when tagged 'tv')
            depth_vis = depth_normalized
            try:
                if DEPTH_VIS_APPLY_TV_RANGE_EXPANSION_10BIT and getattr(self, "previewer", None) is not None:
                    bd = int(getattr(self.previewer, "_depth_bit_depth", 8) or 8)
                    dpath = getattr(self.previewer, "_depth_path", None)
                    if bd >= 10 and isinstance(dpath, str) and dpath:
                        if not hasattr(self, "_depth_color_range_cache"):
                            self._depth_color_range_cache = {}
                        rng = self._depth_color_range_cache.get(dpath)
                        if rng is None:
                            info = get_video_stream_info(dpath)
                            rng = str((info or {}).get("color_range") or (info or {}).get("range") or "").lower()
                            self._depth_color_range_cache[dpath] = rng
                        if rng == "tv":
                            depth_vis = (depth_vis - DEPTH_VIS_TV10_BLACK_NORM) / (
                                DEPTH_VIS_TV10_WHITE_NORM - DEPTH_VIS_TV10_BLACK_NORM
                            )
            except Exception:
                pass
            depth_vis_uint8 = (np.clip(depth_vis, 0, 1) * 255).astype(np.uint8)
            depth_vis_3ch = np.stack([depth_vis_uint8] * 3, axis=-1)
            final_tensor = torch.from_numpy(depth_vis_3ch).permute(2, 0, 1).unsqueeze(0).float().cuda() / 255.0

        elif preview_source == "Depth Map (Color)":
            # Diagnostic color view (visualization-only TV-range expansion for 10-bit depth, when tagged 'tv')
            depth_vis = depth_normalized
            try:
                if DEPTH_VIS_APPLY_TV_RANGE_EXPANSION_10BIT and getattr(self, "previewer", None) is not None:
                    bd = int(getattr(self.previewer, "_depth_bit_depth", 8) or 8)
                    dpath = getattr(self.previewer, "_depth_path", None)
                    if bd >= 10 and isinstance(dpath, str) and dpath:
                        if not hasattr(self, "_depth_color_range_cache"):
                            self._depth_color_range_cache = {}
                        rng = self._depth_color_range_cache.get(dpath)
                        if rng is None:
                            info = get_video_stream_info(dpath)
                            rng = str((info or {}).get("color_range") or (info or {}).get("range") or "").lower()
                            self._depth_color_range_cache[dpath] = rng
                        if rng == "tv":
                            depth_vis = (depth_vis - DEPTH_VIS_TV10_BLACK_NORM) / (
                                DEPTH_VIS_TV10_WHITE_NORM - DEPTH_VIS_TV10_BLACK_NORM
                            )
            except Exception:
                pass
            depth_vis_uint8 = (np.clip(depth_vis, 0, 1) * 255).astype(np.uint8)
            vis_color = cv2.applyColorMap(depth_vis_uint8, cv2.COLORMAP_VIRIDIS)
            vis_rgb = cv2.cvtColor(vis_color, cv2.COLOR_BGR2RGB)
            final_tensor = torch.from_numpy(vis_rgb).permute(2, 0, 1).unsqueeze(0).float().cuda() / 255.0

        # --- Live convergence: keep the two eyes this render produced ---
        # _live_convergence slides them while the Convergence slider is
        # dragged. Kept only for the views that are a composite of exactly
        # these two images; any other render clears it, so a drag in another
        # view waits for the release as before.
        self._live_conv = None
        if right_eye_tensor is not None and preview_source in self._LIVE_CONV_MODES:
            try:
                def _to_u8(t):
                    return (t[0].permute(1, 2, 0) * 255.0).clamp(0, 255).to(torch.uint8).cpu().numpy()

                # Splat Result shows the right eye as displayed, mask
                # highlight and all, which then moves with it.
                shown_right = (final_tensor if preview_source in ("Splat Result", "Splat Result(Low)")
                               else right_eye_tensor)
                _dual = bool(_dual_eye_preview)
                self._live_conv = {
                    "key": self._live_conv_key(preview_source),
                    "conv": float(params["convergence_point"]),
                    # Disparity is (depth - convergence) * 2 * K pixels, and the
                    # warp moves a pixel to x - disparity. So convergence +1
                    # moves the right eye 2K pixels right -- for every pixel,
                    # which is why a shift is the same image the warp would make.
                    "px_per_unit": 2.0 * (float(params["max_disp"]) / 20.0 / 100.0)
                                   * W_target * float(tv_disp_comp),
                    # Dual eye splits it: right eye by the bias, left the rest.
                    "right_frac": (max(0.0, min(1.0, self._safe_float(self.dual_eye_bias_var, 0.5)))
                                   if _dual else 1.0),
                    "dual": _dual,
                    "left": _to_u8(left_eye_tensor_resized),
                    "right": _to_u8(shown_right),
                    "depth": depth_normalized,
                    "params": dict(params),
                }
            except Exception:
                logger.debug("Live convergence: could not keep the rendered eyes", exc_info=True)
                self._live_conv = None

        # --- 3D Modes and SBS Update ---
        _left_hook = getattr(self, "left_eye_hook", None)  # v2: the Depth Map Editor's masks, left eye only
        if _left_hook is not None and left_eye_tensor_resized is not None:
            left_eye_tensor_resized = _left_hook(left_eye_tensor_resized)
        if preview_source == "Anaglyph 3D":
            left_np = (left_eye_tensor_resized.squeeze(0).permute(1, 2, 0).cpu().numpy() * 255).astype(np.uint8)
            right_np = (right_eye_tensor.squeeze(0).permute(1, 2, 0).cpu().numpy() * 255).astype(np.uint8)
            left_gray_np = cv2.cvtColor(left_np, cv2.COLOR_RGB2GRAY)
            anaglyph_np = right_np.copy()
            anaglyph_np[:, :, 0] = left_gray_np
            final_tensor = torch.from_numpy(anaglyph_np).permute(2, 0, 1).unsqueeze(0).float().cuda() / 255.0

        elif preview_source == "Dubois Anaglyph":
            final_tensor = apply_dubois_anaglyph_torch(left_eye_tensor_resized, right_eye_tensor)

        elif preview_source == "Optimized Anaglyph":
            final_tensor = apply_optimized_anaglyph_torch(left_eye_tensor_resized, right_eye_tensor)

        elif preview_source == "ColorCode (Amber/Blue)":
            # Dubois amber/blue. Needs amber-left / dark-blue-right glasses --
            # it will look wrong through red/cyan, which is the format, not a
            # fault in the conversion.
            final_tensor = apply_colorcode_anaglyph_torch(left_eye_tensor_resized, right_eye_tensor)

        elif preview_source == "ColorCode (Blue/Amber)":
            # Same Dubois matrix with the views swapped, for wearing ColorCode
            # glasses back to front. Depth stays correct. Useful because the
            # amber channel carries nearly all the luminance, so which eye it
            # lands on changes how colour-balanced the result feels.
            final_tensor = apply_colorcode_anaglyph_torch(
                left_eye_tensor_resized, right_eye_tensor, swap_eyes=True
            )

        elif preview_source == "Wigglegram":
            self.previewer._start_wigglegram_animation(left_eye_tensor_resized, right_eye_tensor)
            return None

        elif preview_source == "Mesh Warp":
            from core.common.mesh_warp import run_fusion_stereo

            left_np = (left_eye_tensor_resized.squeeze(0).permute(1, 2, 0).cpu().numpy() * 255).astype(np.uint8)
            left_bgr = cv2.cvtColor(left_np, cv2.COLOR_RGB2BGR)

            d_mult = self._safe_float(self.mesh_warp_preview_density_var, 0.5)

            l_img, r_img = run_fusion_stereo(
                image=left_bgr,
                depth=depth_normalized,
                disparity=float(params.get("max_disp", 25.0)),
                convergence=float(params.get("convergence_point", 0.5)),
                view_bias=self._safe_float(self.mesh_warp_view_bias_var, 0.0),
                dolly_zoom=self._safe_float(self.mesh_warp_dolly_zoom_var, 0.0),
                extrusion_scale=self._safe_float(self.mesh_warp_extrusion_scale_var, 0.5),
                density_x=int(left_bgr.shape[1] * d_mult),
                density_y=int(left_bgr.shape[0] * d_mult),
            )

            if getattr(self.previewer, "sbs_cross_eye_var", None) and self.previewer.sbs_cross_eye_var.get():
                sbs_np = np.concatenate([r_img, l_img], axis=1)
            else:
                sbs_np = np.concatenate([l_img, r_img], axis=1)

            sbs_rgb = cv2.cvtColor(sbs_np, cv2.COLOR_BGR2RGB)
            return Image.fromarray(sbs_rgb)

        elif preview_source == "SBS + Mesh":
            from core.common.mesh_warp import run_fusion_stereo

            # Top half: SBS (same as Side-by-Side branch)
            left_np = (left_eye_tensor_resized.squeeze(0).permute(1, 2, 0).cpu().numpy() * 255).astype(np.uint8)
            right_np = (right_eye_tensor.squeeze(0).permute(1, 2, 0).cpu().numpy() * 255).astype(np.uint8)
            if getattr(self.previewer, "sbs_cross_eye_var", None) and self.previewer.sbs_cross_eye_var.get():
                sbs_view = np.concatenate([right_np, left_np], axis=1)
            else:
                sbs_view = np.concatenate([left_np, right_np], axis=1)

            # Bottom half: Mesh Warp
            left_bgr = cv2.cvtColor(left_np, cv2.COLOR_RGB2BGR)
            d_mult = self._safe_float(self.mesh_warp_preview_density_var, 0.5)

            l_img, r_img = run_fusion_stereo(
                image=left_bgr,
                depth=depth_normalized,
                disparity=float(params.get("max_disp", 25.0)),
                convergence=float(params.get("convergence_point", 0.5)),
                view_bias=self._safe_float(self.mesh_warp_view_bias_var, 0.0),
                dolly_zoom=self._safe_float(self.mesh_warp_dolly_zoom_var, 0.0),
                extrusion_scale=self._safe_float(self.mesh_warp_extrusion_scale_var, 0.5),
                density_x=int(left_bgr.shape[1] * d_mult),
                density_y=int(left_bgr.shape[0] * d_mult),
            )
            if getattr(self.previewer, "sbs_cross_eye_var", None) and self.previewer.sbs_cross_eye_var.get():
                mesh_bgr = np.concatenate([r_img, l_img], axis=1)
            else:
                mesh_bgr = np.concatenate([l_img, r_img], axis=1)
            mesh_rgb = cv2.cvtColor(mesh_bgr, cv2.COLOR_BGR2RGB)

            # Width-match if needed
            if sbs_view.shape[1] != mesh_rgb.shape[1]:
                target_w = min(sbs_view.shape[1], mesh_rgb.shape[1])
                sbs_view = cv2.resize(sbs_view, (target_w, sbs_view.shape[0]))
                mesh_rgb = cv2.resize(mesh_rgb, (target_w, mesh_rgb.shape[0]))

            combined = np.concatenate([sbs_view, mesh_rgb], axis=0)
            return Image.fromarray(combined)

        elif preview_source in ("Side-by-Side", "Side-by-Side (Cross-eye)", "Glasses-Free 3D"):
            # Concatenate left and right eye as SBS image
            # v2 (2026-10-11): each eye made uint8 on the GPU, as the final path does -- a quarter of
            # the copy back and no float maths on the CPU (the same values: x*255 truncated)
            left_np = (left_eye_tensor_resized[0].permute(1, 2, 0) * 255.0).clamp(0, 255).to(torch.uint8).cpu().numpy()
            _right_view = right_eye_tensor
            if (preview_source == "Glasses-Free 3D" and occlusion_mask is not None
                    and getattr(self, "mask_highlight_var", None) is not None and self.mask_highlight_var.get()):
                _right_view = apply_mask_highlight_torch(right_eye_tensor, occlusion_mask)  # v2: as on Splat Result
            right_np = (_right_view[0].permute(1, 2, 0) * 255.0).clamp(0, 255).to(torch.uint8).cpu().numpy()
            # The dedicated "(Cross-eye)" source always swaps; the plain SBS
            # source honors the X-key cross-eye toggle. Either way, an active
            # toggle flips the result so both controls compose predictably.
            force_cross = preview_source == "Side-by-Side (Cross-eye)"
            toggle_cross = preview_source != "Glasses-Free 3D" and bool(
                getattr(self.previewer, "sbs_cross_eye_var", None)
                and self.previewer.sbs_cross_eye_var.get()
            )
            if force_cross != toggle_cross:  # XOR: exactly one requests a swap
                sbs_np = np.concatenate([right_np, left_np], axis=1)
            else:
                sbs_np = np.concatenate([left_np, right_np], axis=1)
            sbs_np = self._apply_preview_brightness(sbs_np, params)
            sbs_np = self._fb_maybe_apply(sbs_np, depth_normalized, params, preview_source, sbs=True)
            sbs_img = Image.fromarray(sbs_np)
            if preview_source == "Glasses-Free 3D":
                sbs_img.info["sr3d"] = True   # v2: the glue splits it (studio/sr_display.py)
                sbs_img.info["sr3d_np"] = sbs_np   # ...from this, not by reading the image back
            return sbs_img

        else:
            # For non-3D modes, final_tensor is already set
            pass

        # --- End SBS Update ---

        t_finish = time.perf_counter()

        # 5. Final transfer to CPU and PIL conversion
        t_cpu_start = time.perf_counter()

        # OPTIMIZATION: Scale and cast to uint8 on GPU BEFORE transferring to CPU.
        # This reduces transfer bandwidth by 4x and moves the math to the GPU.
        final_uint8_gpu = (final_tensor[0].permute(1, 2, 0) * 255.0).clamp(0, 255).to(torch.uint8)
        final_np = final_uint8_gpu.cpu().numpy()

        t_cpu_end = time.perf_counter()

        # Cleanup tensors explicitly
        del left_eye_tensor_resized, right_eye_tensor, disp_map_tensor, occlusion_mask
        if "right_eye_tensor_raw" in locals():
            del right_eye_tensor_raw
        del final_uint8_gpu

        # Preview Brightness (view-only): applied BEFORE Frame Break so its
        # bars stay pure black regardless of this setting.
        final_np = self._apply_preview_brightness(final_np, params)

        # Frame Break (Special FX): draw letterbox bars + let near subjects
        # protrude through them. No-op unless Bar Size > 0 and the mode is a
        # viewer-facing one, so every other preview is unchanged.
        final_np = self._fb_maybe_apply(final_np, depth_normalized, params, preview_source, sbs=False)

        pil_img = Image.fromarray(final_np)

        t_all_finish = time.perf_counter()

        logger.debug(
            f"[TIMER] Preview: Total={t_all_finish - t_start:.3f}s | "
            f"Setup={t_setup - t_start:.3f}s | "
            f"Resize={t_resize_depth - t_setup:.3f}s | "
            f"Norm={t_norm - t_resize_depth:.3f}s | "
            f"Metrics={t_metrics - t_norm:.3f}s | "
            f"Warp={t_warp - t_metrics:.3f}s | "
            f"CPU_Xfer={t_cpu_end - t_cpu_start:.3f}s | "
            f"PIL={t_all_finish - t_cpu_end:.3f}s"
        )
        return pil_img

    # -- v1 SplatterGUI.move_sidecars_depth_to_source (splatting_gui.py:8226)
    def move_sidecars_depth_to_source(self):
        """Moves sidecar files from depth folder to source folder, removing _depth suffix."""
        depth_dir = self.input_depth_maps_var.get()
        source_dir = self.input_source_clips_var.get()

        if not os.path.isdir(depth_dir):
            messagebox.showerror("Error", "Depth Maps folder is not set or doesn't exist.")
            return
        if not os.path.isdir(source_dir):
            messagebox.showerror("Error", "Source Clips folder is not set or doesn't exist.")
            return

        sidecar_ext = self.APP_CONFIG_DEFAULTS.get("SIDECAR_EXT", ".fssidecar")

        moved_count = 0
        errors_count = 0

        if not messagebox.askyesno(
            "Sidecars: Depth → Source",
            f"This will move sidecar files from:\n  {depth_dir}\nto:\n  {source_dir}\n\nRemoving '_depth' suffix from filenames.\n\nContinue?",
        ):
            return

        for filename in os.listdir(depth_dir):
            if filename.endswith(sidecar_ext):
                depth_name = filename[: -len(sidecar_ext)]
                if depth_name.endswith("_depth"):
                    source_name = depth_name[:-6] + sidecar_ext
                else:
                    source_name = depth_name + sidecar_ext

                src_path = os.path.join(depth_dir, filename)
                dest_path = os.path.join(source_dir, source_name)

                if os.path.isfile(dest_path):
                    logger.debug(f"Destination sidecar exists, skipping: {source_name}")
                    continue

                try:
                    shutil.move(src_path, dest_path)
                    moved_count += 1
                    logger.debug(f"Moved '{filename}' → '{source_name}'")
                except Exception as e:
                    errors_count += 1
                    logger.error(f"Error moving '{filename}': {e}")

        self.clear_processing_info()
        if hasattr(self, "previewer"):
            self.previewer.reset_video_list_scan()
        self.status_label.configure(text=f"Moved {moved_count} sidecars, {errors_count} errors.")
        messagebox.showinfo("Complete", f"Sidecars moved: {moved_count}\nErrors: {errors_count}")

    # -- v1 SplatterGUI.move_sidecars_source_to_depth (splatting_gui.py:8278)
    def move_sidecars_source_to_depth(self):
        """Moves sidecar files from source folder to depth folder, adding _depth suffix."""
        source_dir = self.input_source_clips_var.get()
        depth_dir = self.input_depth_maps_var.get()

        if not os.path.isdir(source_dir):
            messagebox.showerror("Error", "Source Clips folder is not set or doesn't exist.")
            return
        if not os.path.isdir(depth_dir):
            messagebox.showerror("Error", "Depth Maps folder is not set or doesn't exist.")
            return

        sidecar_ext = self.APP_CONFIG_DEFAULTS.get("SIDECAR_EXT", ".fssidecar")

        moved_count = 0
        errors_count = 0

        if not messagebox.askyesno(
            "Sidecars: Source → Depth",
            f"This will move sidecar files from:\n  {source_dir}\nto:\n  {depth_dir}\n\nAdding '_depth' suffix to filenames.\n\nContinue?",
        ):
            return

        for filename in os.listdir(source_dir):
            if filename.endswith(sidecar_ext):
                source_name = filename[: -len(sidecar_ext)]
                depth_name = source_name + "_depth" + sidecar_ext

                src_path = os.path.join(source_dir, filename)
                dest_path = os.path.join(depth_dir, depth_name)

                if os.path.isfile(dest_path):
                    logger.debug(f"Destination sidecar exists, skipping: {depth_name}")
                    continue

                try:
                    shutil.move(src_path, dest_path)
                    moved_count += 1
                    logger.debug(f"Moved '{filename}' → '{depth_name}'")
                except Exception as e:
                    errors_count += 1
                    logger.error(f"Error moving '{filename}': {e}")

        self.clear_processing_info()
        self.status_label.configure(text=f"Moved {moved_count} sidecars, {errors_count} errors.")
        messagebox.showinfo("Complete", f"Sidecars moved: {moved_count}\nErrors: {errors_count}")

    # -- v1 SplatterGUI.run_preview_auto_converge (splatting_gui.py:8437)
    def run_preview_auto_converge(self, force_run=False):
        """
        Starts the Auto-Convergence pre-pass on the current preview clip in a thread,
        and updates the convergence slider/preview upon completion.
        'force_run=True' is used when triggered by the combo box, as validation is needed.
        """
        if not hasattr(self, "previewer") or not self.previewer.source_readers:
            if force_run:
                messagebox.showwarning("Auto-Converge Preview", "Please load a video in the Previewer first.")
                self.auto_convergence_combo.set("Off")  # Reset combo on fail
            return

        current_index = self.previewer.current_video_index
        if current_index == -1:
            if force_run:
                messagebox.showwarning("Auto-Converge Preview", "No video is currently selected for processing.")
                self.auto_convergence_combo.set("Off")  # Reset combo on fail
            return

        mode = self.auto_convergence_mode_var.get()
        if mode == "Off":
            if force_run:  # This should be caught by the cache check, but as a safeguard
                return
            messagebox.showwarning(
                "Auto-Converge Preview", "Auto-Convergence Mode must be set to 'Average', 'Peak', or 'Hybrid'."
            )
            return

        current_source_dict = self.previewer.video_list[current_index]
        single_video_path = current_source_dict.get("source_video")
        single_depth_path = current_source_dict.get("depth_map")

        # --- Check if calculation is already done for a different mode/path ---
        is_path_mismatch = self.cache.is_auto_conv_stale(single_depth_path)
        is_cache_complete = self.cache.has_auto_conv()

        # If running from the combo box (force_run=True) AND the cache is incomplete
        # BUT the path has changed, we must clear the cache and run.
        if force_run and is_path_mismatch and is_cache_complete:
            logger.info("New video detected. Clearing Auto-Converge cache.")
            self.cache.clear_auto_conv()
            self._auto_conv_cache = self.cache.auto_conv  # keep alias in sync

        # Validate paths
        if (
            not isinstance(single_video_path, str)
            or not os.path.exists(single_video_path)
            or not isinstance(single_depth_path, str)
            or not os.path.exists(single_depth_path)
        ):
            messagebox.showerror(
                "Auto-Converge Preview Error",
                f"Invalid video or depth map path.\nVideo: {single_video_path}\nDepth: {single_depth_path}",
            )
            if force_run:
                self.auto_convergence_combo.set("Off")
            return

        try:
            current_anchor = float(self.zero_disparity_anchor_var.get())
            process_length = int(self.process_length_var.get())
            int(self.batch_size_var.get())  # still validated, as it always was
            gamma = self._safe_float(self.depth_gamma_var, 1.0)
        except ValueError as e:
            messagebox.showerror("Auto-Converge Preview Error", f"Invalid input for slider or process length: {e}")
            if force_run:
                self.auto_convergence_combo.set("Off")
            return

        # Set running flag and disable inputs
        self._is_auto_conv_running = True
        self.btn_auto_converge_preview.configure(state="disabled")
        self.start_button.configure(state="disabled")
        self.start_single_button.configure(state="disabled")
        self.auto_convergence_combo.configure(state="disabled")  # Disable combo during run

        self.status_label.configure(text=f"Auto-Convergence pre-pass started ({mode} mode)...")

        # Start the calculation in a new thread
        # Start the calculation in a new thread
        # batch_size is not an argument of _auto_converge_worker: passing it made
        # seven arguments for six parameters, a TypeError in the thread, so the
        # pre-pass never ran and the button stayed disabled.
        worker_args = (single_video_path, single_depth_path, process_length, current_anchor, gamma, mode)
        self._auto_converge_worker(*worker_args)

    # -- v1 SplatterGUI._dp_total_signature (splatting_gui.py:8524)
    def _dp_total_signature(self, depth_path: str, conv: float, max_disp: float, gamma: float) -> str:
        """Signature for caching Total(D+P) metrics.

        Delegates to AnalysisService.make_dp_cache_key.  Convergence is
        intentionally excluded so slider moves don't bust the cache.
        """
        return AnalysisService.make_dp_cache_key(depth_path, max_disp, gamma)

    # -- v1 SplatterGUI._estimate_dp_total_max_for_depth_video (splatting_gui.py:8532)
    def _estimate_dp_total_max_for_depth_video(
        self,
        depth_path: str,
        convergence_point: float,
        max_disp: float,
        depth_gamma: float,
        sample_frames: int = 10,
        pixel_stride: int = 8,
        total_frames_override: Optional[int] = None,
        *,
        params: Optional[dict] = None,
        sidecar_folder: Optional[str] = None,
        depth_blur_left_mix: Optional[float] = None,
    ) -> Optional[float]:
        """
        Estimates the maximum Total(D+P) for a clip by sampling frames.

        Delegates to AnalysisService.estimate_dp_total_max — all math lives
        there, zero Tkinter dependency.  This wrapper resolves the GUI-specific
        context (previewer size, sidecar folder, norm cache) and passes it in.
        """
        # -- Resolve GUI-specific context ----------------------------------
        depth_native_size = None
        try:
            if self.previewer is not None and getattr(self.previewer, "_depth_path", None) == depth_path:
                out_w = int(getattr(self.previewer, "_depth_native_w", 0) or 0)
                out_h = int(getattr(self.previewer, "_depth_native_h", 0) or 0)
                if out_w and out_h:
                    depth_native_size = (out_w, out_h)
        except Exception:
            depth_native_size = None

        # Both of these used to be read here, on the estimate worker:
        # depth_blur_left_mix_var directly, and multi_map_var /
        # input_depth_maps_var via _get_sidecar_base_folder(). The caller now
        # snapshots them on the main thread and passes them in; the fallbacks
        # below only run for a main-thread caller that passed nothing.
        if sidecar_folder is None:
            try:
                sidecar_folder = self._get_sidecar_base_folder()
            except Exception:
                sidecar_folder = None

        if depth_blur_left_mix is None:
            try:
                depth_blur_left_mix = float(self.depth_blur_left_mix_var.get())
            except Exception:
                depth_blur_left_mix = 0.5
        mix_f = float(depth_blur_left_mix)

        return AnalysisService.estimate_dp_total_max(
            depth_path=depth_path,
            convergence_point=convergence_point,
            max_disp=max_disp,
            depth_gamma=depth_gamma,
            params=params,
            sample_frames=sample_frames,
            pixel_stride=pixel_stride,
            total_frames_override=total_frames_override,
            depth_native_size=depth_native_size,
            sidecar_folder=sidecar_folder,
            clip_norm_cache=self.cache.clip_norm,
            depth_blur_left_mix=mix_f,
        )

    # -- v1 SplatterGUI.run_estimate_dp_total_max (splatting_gui.py:8597)
    def run_estimate_dp_total_max(self):
        """Compute a quick sampled estimate of this clip's Max Total(D+P) and seed the overlay."""
        try:
            if getattr(self, "previewer", None) is None:
                return
            depth_path = getattr(self.previewer, "_depth_path", None)
            if not depth_path:
                return

            try:
                logger.info(f"Estimate Max Total(D+P): sampling clip depth map: {os.path.basename(depth_path)}")
            except Exception:
                pass

            params = None
            try:
                # Use the same parameters the preview processing uses (includes sidecar overrides)
                if getattr(self.previewer, "get_params_callback", None):
                    params = self.previewer.get_params_callback()
            except Exception:
                params = None

            if isinstance(params, dict):
                conv = float(params.get("zero_disparity_anchor", self.zero_disparity_anchor_var.get()))
                max_disp = float(params.get("max_disparity", self.max_disp_var.get()))
                gamma = float(params.get("depth_gamma", self.depth_gamma_var.get()))
            else:
                conv = float(self.zero_disparity_anchor_var.get())
                max_disp = float(self.max_disp_var.get())
                gamma = float(self.depth_gamma_var.get())

            total_frames_override = None
            try:
                # Reuse already-known frame count from the active preview (avoids re-probing/decord hangs)
                if getattr(self, "previewer", None) is not None and hasattr(self.previewer, "frame_scrubber"):
                    total_frames_override = int(self.previewer.frame_scrubber.cget("to")) + 1
            except Exception:
                total_frames_override = None

            sig = self._dp_total_signature(depth_path, conv, max_disp, gamma)

            try:
                if hasattr(self, "btn_est_dp_total"):
                    self.btn_est_dp_total.configure(state="disabled")
            except Exception:
                pass

            est_start_ts = time.time()

            # Snapshot the last two GUI-owned values here, on the main thread.
            # _estimate_dp_total_max_for_depth_video used to read them itself,
            # which put a tk var read (and a second one behind
            # _get_sidecar_base_folder) on the estimate worker.
            try:
                est_sidecar_folder = self._get_sidecar_base_folder()
            except Exception:
                est_sidecar_folder = None
            try:
                est_depth_blur_left_mix = float(self.depth_blur_left_mix_var.get())
            except Exception:
                est_depth_blur_left_mix = 0.5

            def _worker():
                try:
                    est = self._estimate_dp_total_max_for_depth_video(
                        depth_path,
                        conv,
                        max_disp,
                        gamma,
                        sample_frames=10,
                        pixel_stride=8,
                        total_frames_override=total_frames_override,
                        params=params,
                        sidecar_folder=est_sidecar_folder,
                        depth_blur_left_mix=est_depth_blur_left_mix,
                    )
                except Exception as e:
                    try:
                        logger.exception(f"Estimate Max Total(D+P) failed: {e}")
                    except Exception:
                        pass
                    est = None

                def _apply():
                    try:
                        if est is not None:
                            try:
                                logger.info(f"Estimate Max Total(D+P): {float(est):.2f}%")
                            except Exception:
                                pass
                            self.cache.store_dp_est(sig, float(est))
                            if getattr(self, "previewer", None) is not None and hasattr(
                                self.previewer, "set_depth_pop_max_estimate"
                            ):
                                ui_sig = None
                            try:
                                ui_sig = getattr(self.previewer, "_dp_signature", None)
                            except Exception:
                                ui_sig = None
                            if not ui_sig:
                                ui_sig = sig
                            self.previewer.set_depth_pop_max_estimate(float(est), ui_sig)
                    finally:
                        try:
                            if est is None:
                                elapsed = None
                                try:
                                    elapsed = time.time() - est_start_ts
                                except Exception:
                                    pass
                                if elapsed is not None:
                                    logger.info(f"Estimate Max Total(D+P): (no result)  (took {elapsed:.2f}s)")
                                else:
                                    logger.info("Estimate Max Total(D+P): (no result)")
                        except Exception:
                            pass

                        try:
                            if hasattr(self, "btn_est_dp_total"):
                                self.btn_est_dp_total.configure(state="normal")
                        except Exception:
                            pass

                self.after(0, _apply)

            _worker()
        except Exception:
            try:
                if hasattr(self, "btn_est_dp_total"):
                    self.btn_est_dp_total.configure(state="normal")
            except Exception:
                pass

    # -- v1 SplatterGUI._get_cached_dp_total_est_for_current (splatting_gui.py:8730)
    def _get_cached_dp_total_est_for_current(self) -> Optional[float]:
        try:
            if getattr(self, "previewer", None) is None:
                return None
            depth_path = getattr(self.previewer, "_depth_path", None)
            if not depth_path:
                return None
            conv = float(self.zero_disparity_anchor_var.get())
            max_disp = float(self.max_disp_var.get())
            gamma = float(self.depth_gamma_var.get())
            sig = self._dp_total_signature(depth_path, conv, max_disp, gamma)
            return self.cache.get_dp_est(sig)
        except Exception:
            return None

    # -- v1 SplatterGUI._auto_pass_csv_get_path (splatting_gui.py:8745)
    def _auto_pass_csv_get_path(self) -> str:
        try:
            return os.path.join(self._get_sidecar_base_folder(), "auto_pass_export.csv")
        except Exception:
            return "auto_pass_export.csv"

    # -- v1 SplatterGUI._auto_pass_csv_load_cache (splatting_gui.py:8751)
    def _auto_pass_csv_load_cache(self, csv_path: str) -> None:
        """Load CSV rows into memory (keyed by source_video basename)."""
        try:
            self._auto_pass_csv_path = csv_path
            rows = {}
            if os.path.exists(csv_path):
                with open(csv_path, "r", newline="", encoding="utf-8") as f:
                    r = csv.DictReader(f)
                    for row in r:
                        # Prefer source_video as the stable key; fall back to depth_map for older exports.
                        key = str(row.get("source_video", "")).strip()
                        if not key:
                            key = str(row.get("depth_map", "")).strip()
                        if key:
                            rows[key] = dict(row)
            self._auto_pass_csv_cache = rows
        except Exception:
            self._auto_pass_csv_cache = {}

    # -- v1 SplatterGUI._auto_pass_csv_flush_cache (splatting_gui.py:8770)
    def _auto_pass_csv_flush_cache(self, fieldnames: list) -> None:
        try:
            if not self._auto_pass_csv_path or self._auto_pass_csv_cache is None:
                return

            # Always write the CSV (for Resolve / general interoperability)
            with open(self._auto_pass_csv_path, "w", newline="", encoding="utf-8") as f:
                w = csv.DictWriter(f, fieldnames=fieldnames)
                w.writeheader()
                for key in sorted(self._auto_pass_csv_cache.keys()):
                    w.writerow(self._auto_pass_csv_cache[key])

            # TSV export removed (CSV import works fine in LibreOffice after clicking OK).
        except Exception:
            pass

    # -- v1 SplatterGUI._auto_pass_csv_update_row_from_current (splatting_gui.py:8786)
    def _auto_pass_csv_update_row_from_current(self) -> None:
        """Create/update this clip's row in auto_pass_export.csv when sidecar data changes."""
        try:
            csv_path = self._auto_pass_csv_get_path()
            if not csv_path:
                return
            try:
                os.makedirs(os.path.dirname(csv_path), exist_ok=True)
            except Exception:
                pass

            if self._auto_pass_csv_cache is None or self._auto_pass_csv_path != csv_path:
                self._auto_pass_csv_load_cache(csv_path)

            if getattr(self, "previewer", None) is None:
                return
            idx = getattr(self.previewer, "current_video_index", -1)
            if idx is None or idx < 0:
                return
            src = self.previewer.video_list[idx].get("source_video", "")
            depth = self.previewer.video_list[idx].get("depth_map", "")
            depth_bn = os.path.basename(depth) if depth else ""
            src_bn = os.path.basename(src) if src else ""
            if not src_bn and not depth_bn:
                return

            # Frame token: last underscore + digits at end of source basename (before extension).
            frame_num = ""
            try:
                stem = os.path.splitext(src_bn)[0]
                mfr = re.search(r"_([0-9]+)$", stem)
                frame_num = mfr.group(1) if mfr else ""
            except Exception:
                frame_num = ""
            if not frame_num:
                # Fallback: try depth basename pattern "..._<digits>_depth"
                try:
                    stem = os.path.splitext(depth_bn)[0]
                    if stem.endswith("_depth"):
                        stem = stem[:-6]
                    mfr = re.search(r"_([0-9]+)$", stem)
                    frame_num = mfr.group(1) if mfr else ""
                except Exception:
                    frame_num = ""

            res = self._get_current_sidecar_paths_and_data()
            if not res:
                return
            _, _, current_data = res

            dp_est = self._get_cached_dp_total_est_for_current()
            if dp_est is None:
                try:
                    dp_est = current_data.get("dp_total_max_est", None)
                except Exception:
                    dp_est = None

            # Best-effort: measured (render-time) max Total(D+P), if available
            dp_true = None
            try:
                sig = self._dp_total_signature(
                    depth,
                    float(current_data.get("convergence_plane", 0.5)),
                    float(current_data.get("max_disparity", 0.0)),
                    float(current_data.get("gamma", 1.0)),
                )
                dp_true = self.cache.get_dp_true(sig)
            except Exception:
                dp_true = None
            if dp_true is None:
                try:
                    dp_true = current_data.get("dp_total_max_true", None)
                except Exception:
                    dp_true = None

            existing = dict(self._auto_pass_csv_cache.get(src_bn, {}))
            row = dict(existing)
            row.update(
                {
                    "frame": frame_num,
                    "source_video": src_bn,
                    "selected_depth_map": str(current_data.get("selected_depth_map", "")),
                    "convergence_plane": round(float(current_data.get("convergence_plane", 0.5)), 6),
                    "left_border": round(float(current_data.get("left_border", 0.0)), 3),
                    "right_border": round(float(current_data.get("right_border", 0.0)), 3),
                    "border_mode": str(current_data.get("border_mode", "")),
                    "set_disparity": round(float(current_data.get("max_disparity", 0.0)), 3),
                    "gamma": round(float(current_data.get("gamma", 1.0)), 3),
                }
            )
            if dp_true is not None:
                try:
                    row["true_max_disp"] = round(float(dp_true), 3)
                except Exception:
                    row["true_max_disp"] = dp_true
            if dp_est is not None:
                try:
                    row["est_max_disp"] = round(float(dp_est), 3)
                except Exception:
                    row["est_max_disp"] = dp_est

            # Key by source basename (stable + avoids collisions across multi-map folders).
            self._auto_pass_csv_cache[src_bn] = row

            fieldnames = [
                "frame",
                "source_video",
                "selected_depth_map",
                "convergence_plane",
                "left_border",
                "right_border",
                "border_mode",
                "set_disparity",
                "true_max_disp",
                "est_max_disp",
                "gamma",
            ]
            self._auto_pass_csv_flush_cache(fieldnames)
        except Exception:
            pass

    # -- v1 SplatterGUI._save_current_sidecar_data (splatting_gui.py:9036)
    def _save_current_sidecar_data(
        self,
        is_auto_save: bool = False,
        force_auto_L: Optional[float] = None,
        force_auto_R: Optional[float] = None,
        extra_data: Optional[dict] = None,
    ) -> bool:
        """Core method to prepare data and save the sidecar file.

        extra_data is merged last, for a caller that owns keys this method knows
        nothing about -- the Subs editor's submask_* set. It goes through here
        rather than writing the file itself so a clip that had no sidecar gets
        one built from the CURRENT GUI values. A sidecar assembled any other way
        is a trap: load_sidecar_data() merges defaults into whatever it reads,
        so a file written from it carries a full set of default disparity,
        gamma, dilate and blur values, and "Update Slider from Sidecar" then
        pushes those into the GUI the next time the clip loads -- silently
        replacing the settings the user had.
        """
        result = self._get_current_sidecar_paths_and_data()
        if result is None:
            if not is_auto_save:
                messagebox.showwarning("Sidecar Save", "Please load a video in the Previewer first.")
            return False

        json_sidecar_path, depth_map_path, current_data = result

        # 1. Get current GUI values using the centralized manager
        try:
            # Automate parameters that map directly
            gui_save_data = self.sidecar_manager.capture_from_gui(self.__dict__, mapping=self.GUI_SIDECAR_VAR_MAP)

            # Add specific formatting/overrides
            # Depth Boost keys (not in SIDECAR_KEY_MAP; batch reads them as
            # unknown-preserved keys). Only write when active to keep sidecars lean.
            _b_amt = self._safe_float(self.boost_amount_var, 0.0)
            # Always write Amount, including 0 -- otherwise a clip that previously
            # had a boost saved could never have it explicitly turned back off via
            # Update Sidecar (0 would just leave the old nonzero value on disk).
            gui_save_data["boost_amount"] = _b_amt
            if _b_amt > 0.0:
                gui_save_data["boost_thresh"] = self._safe_float(self.boost_thresh_var, 0.85)
                gui_save_data["boost_curve"] = self._safe_float(self.boost_curve_var, 2.0)
                gui_save_data["boost_knee"] = self._safe_float(self.boost_knee_var, 0.0)
                gui_save_data["boost_prefilter_radius"] = int(
                    self._safe_float(self.boost_prefilter_radius_var, 0)
                )
                gui_save_data["boost_prefilter_eps"] = self._safe_float(self.boost_prefilter_eps_var, 1e-3)

            # Frame Break keys, same convention as boost above: always write
            # the bars amount (including 0, so Update Sidecar can clear a
            # previously-saved frame break), write the threshold only when
            # bars are active. Round-trips as an unknown-preserved sidecar key.
            _fb_bars = self._safe_float(self.frame_break_bars_var, 0.0)
            gui_save_data["frame_break_bars"] = _fb_bars
            if _fb_bars > 0.0:
                gui_save_data["frame_break_thresh"] = self._safe_float(self.frame_break_thresh_var, 1.0)
                gui_save_data["frame_break_erode_left"] = self._safe_float(self.fb_erode_left_var, 0.0)
                gui_save_data["frame_break_erode_right"] = self._safe_float(self.fb_erode_right_var, 0.0)
                gui_save_data["frame_break_erode_global"] = self._safe_float(self.fb_erode_global_var, 0.0)
                gui_save_data["frame_break_edge_blur"] = self._safe_float(self.fb_edge_blur_var, 0.0)

            # Localized Dilate regions. Stripped when empty so untouched clips
            # gain no new sidecar keys (same convention as boost_*).
            dilate_regions.inject_into_sidecar_dict(gui_save_data, self.dilate_regions)

            # Keyframe track (Special FX > Keyframe). Stripped when empty so
            # untouched clips gain no new sidecar keys (same convention).
            keyframes.inject_into_sidecar_dict(gui_save_data, self.keyframe_track)

            gui_save_data["gamma"] = float(f"{self._safe_float(self.depth_gamma_var, 1.0):.2f}")
            gui_save_data["depth_blur_left"] = int(round(self._safe_float(self.depth_blur_left_var)))

            # 2. Geometric logic (Width/Bias -> Left/Right) handled by manager
            w = self._safe_float(self.border_width_var)
            b = self._safe_float(self.border_bias_var)
            left_b, right_b = self.sidecar_manager.calculate_borders_from_width_bias(w, b)

            gui_save_data["left_border"] = left_b
            gui_save_data["right_border"] = right_b

            # 3. Auto Adv values
            gui_save_data["auto_border_L"] = (
                force_auto_L if force_auto_L is not None else self._safe_float(self.auto_border_L_var)
            )
            gui_save_data["auto_border_R"] = (
                force_auto_R if force_auto_R is not None else self._safe_float(self.auto_border_R_var)
            )

            # Transfer all to the final save dictionary.
            #
            # update() can add and overwrite but never delete, and current_data
            # came off the previous on-disk sidecar -- including any key the
            # inject_into_sidecar_dict() calls above deliberately left out of
            # gui_save_data because the correction is now empty. Without this,
            # clearing a Dilate region or a keyframe track
            # and re-saving left the old data on disk, and it kept being applied
            # at render time. The keys come from the modules that own them so
            # this cannot drift out of sync with them.
            for _stripped_key in (
                "stretch_corrections",      # Stretch Paint's (removed 2026-10-09): dropped from old sidecars
                dilate_regions.SIDECAR_KEY,
                keyframes.SIDECAR_KEY,
            ):
                if _stripped_key not in gui_save_data:
                    current_data.pop(_stripped_key, None)

            current_data.update(gui_save_data)

            # Caller-owned keys last, so they win over anything captured above.
            if extra_data:
                current_data.update(extra_data)

            # 4. Filter for export (preserve metric estimates)
            if self.cache.dp_total_max_seen is not None:
                current_data["dp_total_max_est"] = round(float(self.cache.dp_total_max_seen), 6)

        except Exception as e:
            logger.error(f"Error during sidecar save: {e}", exc_info=True)
            if not is_auto_save:
                messagebox.showerror("Sidecar Error", f"Failed to prepare sidecar data: {e}")
            return False

        # 5. Write the updated data back to the file using the manager
        sidecar_existed_before = os.path.exists(json_sidecar_path)
        if self.sidecar_manager.save_sidecar_data(json_sidecar_path, current_data):
            action = "Auto-Saved" if is_auto_save else ("Updated" if sidecar_existed_before else "Created")
            logger.info(f"{action} sidecar: {os.path.basename(json_sidecar_path)}")
            self.status_label.configure(text=f"{action} sidecar.")
            self._update_sidecar_button_text()

            # If an AUTO-PASS CSV exists, keep its row in sync with sidecar edits
            try:
                self._auto_pass_csv_update_row_from_current()
            except Exception:
                pass
            return True
        else:
            logger.error(f"Sidecar Save: Failed to write sidecar file '{os.path.basename(json_sidecar_path)}'.")
            if not is_auto_save:
                messagebox.showerror(
                    "Sidecar Error", f"Failed to write sidecar file '{os.path.basename(json_sidecar_path)}'."
                )
            return False

    # -- v1 SplatterGUI._m2s_render_settings (splatting_gui.py:10559)
    def _m2s_render_settings(self) -> dict:
        """The four M2S selections, normalised, as the renderer wants them.

        One place rather than four: these go to the render, to the preview
        settings dict and to both preview warp calls, and a preview that
        disagreed with the render about which backend is in use would be
        worse than no preview at all.
        """
        return {
            "splat_backend": str(self.splat_backend_var.get() or "SC"),
            "hybrid_sensitivity": max(0.0, min(100.0, self._safe_float(
                self.hybrid_mask_sensitivity_var, 50.0))),
            "hybrid_taper": bool(self.hybrid_mask_taper_var.get()),
            "m2s_fix_strength": max(0.50, min(2.00, self._safe_float(
                self.m2s_fix_strength_var, 1.0))),
        }

    # -- v1 SplatterGUI._apply_preview_overlay_toggles (splatting_gui.py:10655)
    def _apply_preview_overlay_toggles(self):
        """Apply preview-only overlay toggles to the previewer (Crosshair + D/P)."""
        if not getattr(self, "previewer", None):
            return

        try:
            self.previewer.set_crosshair_settings(
                self.crosshair_enabled_var.get(), self.crosshair_white_var.get(), self.crosshair_multi_var.get()
            )
        except Exception:
            pass

        # A loaded config can turn Crosshair on without the checkbox being
        # clicked, so the options follow the variable here too.
        self._update_crosshair_options()

        try:
            getattr(self.previewer, "set_depth_pop_enabled", lambda *_: None)(self.depth_pop_enabled_var.get())
        except Exception:
            pass

    # -- v1 SplatterGUI._update_clip_state_and_text (splatting_gui.py:10698)
    def _update_clip_state_and_text(self):
        """Combines state and text updates for the Sidecar button, run after a new video loads."""

        # 1. Update the button text (Create vs Update)
        if hasattr(self, "_update_sidecar_button_text"):
            self._update_sidecar_button_text()

        # 2. Update the button state (Normal vs Disabled by Override)
        if hasattr(self, "_toggle_sidecar_update_button_state"):
            self._toggle_sidecar_update_button_state()

        # 3. Update the info panel to reflect the currently loaded preview clip
        self._update_processing_info_for_preview_clip()

        # 4. Restore slider values from this clip's sidecar. This is the hook that
        # reliably fires on the initial auto-loaded clip (the navigate callback may
        # only fire on manual prev/next). The helper is idempotent per clip, so if
        # both callbacks fire for one load the restore is applied only once.
        self._restore_sliders_from_current_sidecar()

    # -- v1 SplatterGUI._update_processing_info_for_preview_clip (splatting_gui.py:10718)
    def _update_processing_info_for_preview_clip(self):
        """Updates the 'Current Processing Information' panel to reflect the currently loaded preview clip."""
        try:
            if not getattr(self, "previewer", None):
                return

            idx = getattr(self.previewer, "current_video_index", -1)
            video_list = getattr(self.previewer, "video_list", []) or []
            if not (0 <= idx < len(video_list)):
                return

            source_dict = video_list[idx] if isinstance(video_list[idx], dict) else {}

            # Filename (the main thing you care about in practice)
            src_path = source_dict.get("source_video")
            if src_path:
                new_name = os.path.basename(src_path)
                if self.processing_filename_var.get() != new_name:
                    self.processing_filename_var.set(new_name)
            # Map display during preview:
            # - Normal mode: keep blank (map is already implied by the UI and filename prefix).
            # - Multi-Map mode: show the currently selected map label (same text as the selector),
            #   because the radio dot can be hard to see (e.g., with 3D glasses).
            try:
                if self.multi_map_var.get():
                    sel_map = (self.selected_depth_map_var.get() or "").strip()
                    if sel_map and self.processing_map_var.get() != sel_map:
                        self.processing_map_var.set(sel_map)
                else:
                    if self.processing_map_var.get() != "":
                        self.processing_map_var.set("")
            except Exception:
                # Fail closed: don't spam logs; leave whatever is currently displayed.
                pass

            # Task name: keep stable during preview
            new_task = "Preview"
            if self.processing_task_name_var.get() != new_task:
                self.processing_task_name_var.set(new_task)

            # Frames display: keep stable during preview; show total frames only
            try:
                to_val = self.previewer.frame_scrubber.cget("to")
                total_frames = int(float(to_val)) + 1 if to_val is not None else None

                if total_frames is not None:
                    new_frames = f"{total_frames}"
                    if self.processing_frames_var.get() != new_frames:
                        self.processing_frames_var.set(new_frames)
            except Exception:
                pass

        except Exception as e:
            logger.debug(f"Preview info update skipped due to error: {e}")

    # -- v1 SplatterGUI.update_gui_from_sidecar (splatting_gui.py:10773)
    def update_gui_from_sidecar(self, depth_map_path: str):
        """Reads the sidecar config for the given depth map path and updates GUI sliders."""
        _kept = None  # v2: the same clip again, no sidecar: its per-clip settings stay (see gen PATCHES)
        try:
            _pvw = getattr(self, "previewer", None)
            _src = (_pvw.video_list[_pvw.current_video_index].get("source_video")
                    if _pvw is not None and 0 <= _pvw.current_video_index < len(_pvw.video_list) else None)
            if (_src and _src == getattr(self, "_last_loaded_source_video", None) and depth_map_path
                    and (not self.update_slider_from_sidecar_var.get() or not os.path.exists(
                        self.sidecar_manager.resolve_sidecar_path(depth_map_path, self._get_sidecar_base_folder(),
                                                                  self.APP_CONFIG_DEFAULTS["SIDECAR_EXT"])))):
                _kept = {"vars": {_n: getattr(self, _n).get() for _n in (
                    "boost_amount_var", "pop_amount_var", "frame_break_bars_var", "fb_erode_left_var",
                    "fb_erode_right_var", "fb_erode_global_var", "fb_edge_blur_var")},
                    "keyframes": self.keyframe_track, "dilate": self.dilate_regions}
        except Exception:
            _kept = None
        # Pop Out Boost is scene-specific, not a persistent setting -- leaving it
        # dialed in would silently boost the brightest/nearest thing in whatever
        # clip loads next. Every clip load starts from Amount = 0 unconditionally
        # (independent of the "Update Slider from Sidecar" toggle below); the only
        # way to carry a boost forward is to have explicitly saved it into that
        # clip's own sidecar via Create/Update Sidecar, in which case the sync
        # further down restores it from the file. Threshold/Curve are left alone
        # -- they're inert while Amount is 0.
        self.boost_amount_var.set(0.0)
        self.pop_amount_var.set(0.0)

        # Keyframes are per-clip data just like Boost Amount above: they must
        # never carry over from whatever clip was loaded before. Reset here,
        # unconditionally, then restore from THIS clip's own sidecar below if
        # one exists (same "Update Slider from Sidecar" gating as everything
        # else in this function).
        self.keyframe_track = keyframes.KeyframeTrack()
        self._kf_redraw_markers()
        self._kf_refresh_summary()

        # Frame Break is per-clip too (a shot-by-shot creative choice, and the
        # bar fraction that yields a given aspect ratio depends on THIS source's
        # dimensions). Reset bars to 0 here, unconditionally, then restore from
        # this clip's own sidecar below if saved -- so a clip shows frame break
        # only when its sidecar has it. Rebuild the Letterbox Size buttons for the
        # new source's aspect ratio either way (this always runs, even when
        # sidecar sync is off or absent, so the offered presets stay correct).
        self._fb_setting_preset = True
        try:
            self.frame_break_bars_var.set(0.0)
        finally:
            self._fb_setting_preset = False
        # Edge fine-tuning is per-clip too; zero it on load, restore from sidecar below.
        self.fb_erode_left_var.set(0.0)
        self.fb_erode_right_var.set(0.0)
        self.fb_erode_global_var.set(0.0)
        self.fb_edge_blur_var.set(0.0)
        self._fb_refresh_presets()

        # Hole Shift (dilate_regions) is per-clip region data, same as
        # Boost/Keyframes/Frame Break above --
        # but until now their reset lived AFTER the "Update Slider from
        # Sidecar" guard and the sidecar-exists check further down, instead of
        # up here with the others. That meant a fresh clip with no sidecar
        # yet, or that checkbox turned off, skipped the reset entirely and
        # left whichever clip was open before still dialed in: not a display
        # problem, the actual region data carried over. Unconditional reset
        # here, then the existing restore-from-sidecar block below still
        # overwrites this with the real thing if this clip has one saved.
        self.dilate_regions = dilate_regions.DilateRegions()

        if _kept is not None:  # v2: back as the clip was just at
            self._fb_setting_preset = True
            try:
                for _n, _v in _kept["vars"].items():
                    getattr(self, _n).set(_v)
            finally:
                self._fb_setting_preset = False
            self.keyframe_track, self.dilate_regions = _kept["keyframes"], _kept["dilate"]
            self._kf_redraw_markers()
            self._kf_refresh_summary()
            self._fb_refresh_presets()

        # 1. Video Change Detection (for suppression flag)
        current_source_video = None
        if (
            hasattr(self, "previewer")
            and self.previewer
            and 0 <= self.previewer.current_video_index < len(self.previewer.video_list)
        ):
            current_source_video = self.previewer.video_list[self.previewer.current_video_index].get("source_video")

        if current_source_video and current_source_video != getattr(self, "_last_loaded_source_video", None):
            self._suppress_sidecar_map_update = False
            self._last_loaded_source_video = current_source_video

        if not self.update_slider_from_sidecar_var.get() or not depth_map_path:
            return

        # 2. Resolve sidecar path and load data
        sidecar_ext = self.APP_CONFIG_DEFAULTS["SIDECAR_EXT"]
        sidecar_folder = self._get_sidecar_base_folder()
        json_sidecar_path = self.sidecar_manager.resolve_sidecar_path(depth_map_path, sidecar_folder, sidecar_ext)

        if not os.path.exists(json_sidecar_path):
            self._on_map_selection_changed(from_sidecar=False)
            return

        sidecar_config = self.sidecar_manager.load_sidecar_data(json_sidecar_path)
        logger.info(f"Updating sliders from sidecar: {os.path.basename(json_sidecar_path)}")

        # 3. Bulk sync to GUI vars
        self._suppress_buffer_invalidation = True
        try:
            self.sidecar_manager.sync_to_gui(sidecar_config, self.__dict__, mapping=self.GUI_SIDECAR_VAR_MAP)

            # Localized Dilate regions travel with the sidecar.
            self.dilate_regions = dilate_regions.DilateRegions.from_dict(
                sidecar_config.get(dilate_regions.SIDECAR_KEY)
            )

            # Keyframe track travels with the sidecar too -- restores whatever
            # was explicitly saved for THIS clip (empty track already set
            # above covers every other clip).
            self.keyframe_track = keyframes.KeyframeTrack.from_dict(
                sidecar_config.get(keyframes.SIDECAR_KEY)
            )
            self._kf_redraw_markers()
            self._kf_refresh_summary()

            # Frame Break travels with the sidecar too (unknown-preserved keys,
            # like boost_*). Restore whatever THIS clip saved; the reset above
            # already zeroed bars for every clip that saved nothing.
            try:
                _fb = sidecar_config.get("frame_break_bars")
                if _fb is not None:
                    self._fb_setting_preset = True
                    try:
                        self.frame_break_bars_var.set(float(_fb))
                    finally:
                        self._fb_setting_preset = False
                _fbt = sidecar_config.get("frame_break_thresh")
                if _fbt is not None:
                    self.frame_break_thresh_var.set(float(_fbt))
                for _k, _v in (
                    ("frame_break_erode_left", self.fb_erode_left_var),
                    ("frame_break_erode_right", self.fb_erode_right_var),
                    ("frame_break_erode_global", self.fb_erode_global_var),
                    ("frame_break_edge_blur", self.fb_edge_blur_var),
                ):
                    _val = sidecar_config.get(_k)
                    if _val is not None:
                        _v.set(float(_val))
                self._fb_refresh_presets()
            except Exception:
                pass

            # Depth pre-processing (Edge Alignment) travels with the sidecar
            # too, whenever the render would use it (Sidecar Blur/Dilate on).
            # These were never loaded into the sliders, so the preview had to
            # force the sidecar's values over the sliders to match the render
            # -- which left the sliders doing nothing visible until Update
            # Sidecar. Loading them here makes the sliders show the clip's real
            # values, and lets the preview use the sliders like every other
            # sidecar-backed setting (see get_current_preview_settings).
            if self.enable_sidecar_blur_dilate_var.get():
                try:
                    for _k, _v in (
                        ("depth_dilate_size_x", self.depth_dilate_size_x_var),
                        ("depth_dilate_size_y", self.depth_dilate_size_y_var),
                        ("depth_blur_size_x", self.depth_blur_size_x_var),
                        ("depth_blur_size_y", self.depth_blur_size_y_var),
                        ("depth_dilate_left", self.depth_dilate_left_var),
                        ("depth_blur_left", self.depth_blur_left_var),
                        ("depth_blur_left_mix", self.depth_blur_left_mix_var),
                    ):
                        _val = sidecar_config.get(_k)
                        if _val is not None:
                            _v.set(float(_val))
                except Exception:
                    logger.debug("Sidecar edge settings could not be loaded into sliders", exc_info=True)

            # Ensure flip horizontal is in sync with the previewer
            if hasattr(self, "previewer") and self.previewer:
                self.previewer.flip_horizontal = self.flip_horizontal_var.get()

            # 4. Handle Programmatic Updates (sliders with coupled logic)

            # Convergence
            conv_val = sidecar_config.get("convergence_plane", self.zero_disparity_anchor_var.get())
            if self.set_convergence_value_programmatically:
                self.set_convergence_value_programmatically(conv_val)

            # 5. Seed preview Overlay metrics
            try:
                disp_val = sidecar_config.get("max_disparity", self.max_disp_var.get())
                gamma_val = sidecar_config.get("gamma", self.depth_gamma_var.get())
                dp_seed = sidecar_config.get("dp_total_max_true") or sidecar_config.get("dp_total_max_est")
                if (
                    dp_seed is not None
                    and getattr(self, "previewer", None)
                    and hasattr(self.previewer, "set_depth_pop_max_estimate")
                ):
                    sig = self._dp_total_signature(depth_map_path, conv_val, disp_val, gamma_val)
                    self.previewer.set_depth_pop_max_estimate(float(dp_seed), sig)
            except Exception:
                pass

            # 6. Border Geometry (Left/Right -> Width/Bias)
            left_b = sidecar_config.get("left_border", 0.0)
            right_b = sidecar_config.get("right_border", 0.0)
            w, b = self.sidecar_manager.calculate_width_bias_from_borders(left_b, right_b)

            self.border_width_var.set(f"{w:.2f}")
            self.border_bias_var.set(f"{b:.2f}")

            if self.set_border_width_programmatically:
                self.set_border_width_programmatically(w)
            if self.set_border_bias_programmatically:
                self.set_border_bias_programmatically(b)

            # 7. Post-update cleanup
            self._on_border_mode_change()
            if hasattr(self, "slider_label_updaters"):
                for updater in self.slider_label_updaters:
                    updater()

            # Resync processing queue
            if hasattr(self.previewer, "video_list") and hasattr(self, "resolution_output_list"):
                for i, video_entry in enumerate(self.previewer.video_list):
                    if i < len(self.resolution_output_list):
                        self.resolution_output_list[i].depth_map = video_entry.get("depth_map", None)
        finally:
            self._suppress_buffer_invalidation = False

        # Refresh preview
        self.on_slider_release(None, immediate=True)

    # -- v1 SplatterGUI._update_sidecar_button_text (splatting_gui.py:10980)
    def _update_sidecar_button_text(self):
        """Checks if a sidecar exists for the current preview video and updates the button text."""
        is_sidecar_present = False

        if 0 <= self.previewer.current_video_index < len(self.previewer.video_list):
            current_source_dict = self.previewer.video_list[self.previewer.current_video_index]
            depth_map_path = current_source_dict.get("depth_map")

            if depth_map_path:
                depth_map_basename = os.path.splitext(os.path.basename(depth_map_path))[0]
                sidecar_ext = self.APP_CONFIG_DEFAULTS["SIDECAR_EXT"]
                sidecar_folder = self._get_sidecar_base_folder()  # Use proper folder for multi-map mode
                json_sidecar_path = os.path.join(sidecar_folder, f"{depth_map_basename}{sidecar_ext}")
                is_sidecar_present = os.path.exists(json_sidecar_path)

        button_text = "Update Sidecar" if is_sidecar_present else "Create Sidecar"
        # Through the same transform the button was built with, or a clip
        # load relabels it in title case among buttons that are all caps.
        self.update_sidecar_button.configure(text=app_fonts.button_text(button_text))

    # -- v1 SplatterGUI.update_sidecar_file (splatting_gui.py:11000)
    def update_sidecar_file(self):
        """
        Saves the current GUI values to the sidecar file after checking for user confirmation.
        """
        # 1. Get current sidecar path and data (needed for overwrite check)
        result = self._get_current_sidecar_paths_and_data()
        if result is None:
            messagebox.showwarning("Sidecar Action", "Please load a video in the Previewer first.")
            return

        json_sidecar_path, _, _ = result
        is_sidecar_present = os.path.exists(json_sidecar_path)

        # 2. Conditional Confirmation Dialog
        if is_sidecar_present:
            title = "Overwrite Sidecar File?"
            message = (
                f"This will overwrite parameters (Convergence, Disparity, Gamma, Borders) "
                f"in the existing sidecar file:\n\n{os.path.basename(json_sidecar_path)}\n\n"
                f"Do you want to continue?"
            )
            if not messagebox.askyesno(title, message):
                self.status_label.configure(text="Sidecar update cancelled.")
                return

        # 3. Call the core saving function
        if self._save_current_sidecar_data(is_auto_save=False):
            # Immediately refresh the preview to show the *effect* of the newly saved sidecar
            self.on_slider_release(None)
            # If an AUTO-PASS CSV exists, keep its row in sync with sidecar edits
            try:
                self._auto_pass_csv_update_row_from_current()
            except Exception:
                pass

    # -- v1 SplatterGUI._add_test_label (splatting_gui.py:11035)
    def _add_test_label(self, pil_img: Image.Image, label_text: str) -> Image.Image:
        """Return a copy of pil_img with a red upper-left diagnostic label."""
        if pil_img is None:
            return pil_img
        try:
            out = pil_img.convert("RGB").copy()
            draw = ImageDraw.Draw(out)
            try:
                font_size = max(12, min(28, int(out.size[1] * 0.035)))
                font = ImageFont.truetype("DejaVuSans.ttf", font_size)
            except Exception:
                try:
                    font_size = max(12, min(28, int(out.size[1] * 0.035)))
                    font = ImageFont.truetype("arial.ttf", font_size)
                except Exception:
                    font = ImageFont.load_default()

            txt = str(label_text or "").strip()
            if not txt:
                return out

            try:
                bbox = draw.textbbox((0, 0), txt, font=font)
                tw, th = (bbox[2] - bbox[0]), (bbox[3] - bbox[1])
            except Exception:
                tw, th = draw.textsize(txt, font=font)

            pad_x = max(6, int(round(out.size[0] * 0.008)))
            pad_y = max(4, int(round(out.size[1] * 0.008)))
            x = pad_x
            y = pad_y

            # Thin black backing for readability without changing the image much.
            rect = [x - 3, y - 2, x + tw + 3, y + th + 2]
            draw.rectangle(rect, fill=(0, 0, 0))
            draw.text((x, y), txt, fill=(255, 0, 0), font=font)
            return out
        except Exception:
            return pil_img.copy() if hasattr(pil_img, "copy") else pil_img

    # -- v1 SplatterGUI._handle_gui_diagnostic_capture (splatting_gui.py:11075)
    def _handle_gui_diagnostic_capture(self, payload):
        """Save Map Test / Splat Test outputs from a single-frame diagnostic render capture.

        Triggered when settings.is_test_mode=True and RenderProcessor posts a
        ("diagnostic_capture", grid_rgb_float01) message to the progress queue.
        """
        pending = getattr(self, "_diag_test_pending", None)
        if not pending:
            return

        grid = payload.get("grid") if isinstance(payload, dict) else payload
        if grid is None:
            return

        try:
            output_dir = (
                pending.get("output_dir")
                or getattr(self, "output_splatted_var", tk.StringVar(value="")).get()
                or os.getcwd()
            )
            os.makedirs(output_dir, exist_ok=True)

            test_type = str(pending.get("test_type") or "test").lower()
            video_base = str(pending.get("video_base") or "capture")
            frame_idx = int(pending.get("frame_idx") or 0)
            ffmpeg_tag = str(pending.get("ffmpeg_tag") or "")

            task_name = ""
            if isinstance(payload, dict):
                task_name = str(payload.get("task_name") or "")
            if not task_name:
                task_name = str(getattr(self, "_diag_last_task_name", "") or "")
            task_name = re.sub(r"[^A-Za-z0-9_-]+", "", task_name) if task_name else ""
            if not task_name:
                task_name = "Render"

            task_name_lower = task_name.lower()
            if task_name_lower in ("hires", "fullres", "full-resolution", "full"):
                task_suffix = "Full"
            elif task_name_lower in ("lowres", "low-resolution", "low"):
                task_suffix = "Low"
            else:
                task_suffix = task_name

            g = np.clip(grid, 0.0, 1.0)
            g8 = (g * 255.0 + 0.5).astype(np.uint8)
            pil_grid = Image.fromarray(g8, mode="RGB")

            w, h = pil_grid.size
            hw = w // 2
            hh = h // 2

            render_img = pil_grid
            if hw > 0 and hh > 0 and (w >= 2 and h >= 2):
                if test_type.startswith("map"):
                    # RenderProcessor now forces 4-panel grid for tests; depth is top-right.
                    render_img = pil_grid.crop((hw, 0, w, hh))
                elif test_type.startswith("splat"):
                    # RenderProcessor now forces 4-panel grid for tests; splat result is bottom-right.
                    render_img = pil_grid.crop((hw, hh, w, h))

            preview_img = pending.get("preview_img", None)

            kind = (
                "maptest" if test_type.startswith("map") else ("splattest" if test_type.startswith("splat") else "test")
            )
            stem = f"{video_base}_frame_{frame_idx:05d}_{kind}"

            preview_labeled = (
                self._add_test_label(preview_img, f"Preview-{task_suffix}") if preview_img is not None else None
            )
            render_labeled = self._add_test_label(render_img, f"Render-{task_suffix}")

            preview_path = os.path.join(output_dir, f"{stem}_preview_{task_name}{ffmpeg_tag}.png")
            render_path = os.path.join(output_dir, f"{stem}_render_{task_name}{ffmpeg_tag}.png")
            sbs_path = os.path.join(output_dir, f"{stem}_SBS_{task_name}{ffmpeg_tag}.png")

            if preview_labeled is not None:
                preview_labeled.save(preview_path)

            render_labeled.save(render_path)

            if preview_labeled is not None:
                if preview_labeled.size != render_labeled.size:
                    render_for_sbs = render_labeled.resize(preview_labeled.size, Image.BILINEAR)
                else:
                    render_for_sbs = render_labeled
                sbs = Image.new("RGB", (preview_labeled.size[0] * 2, preview_labeled.size[1]))
                sbs.paste(preview_labeled, (0, 0))
                sbs.paste(render_for_sbs, (preview_labeled.size[0], 0))
                sbs.save(sbs_path)

            logger.info(f"Test outputs saved to: {output_dir} ({kind}:{task_name}{ffmpeg_tag})")
        except Exception as e:
            logger.error(f"Diagnostic capture save failed: {e}", exc_info=True)
